# ------------------------------------------------------------------------------------------------ shared with the
# earlier kits (taken from build_standalone.RUNTIME by report 0053's builder, verbatim)
def say(line):
    print(line, flush=True)


def sha(b):
    return hashlib.sha256(b).hexdigest()


def inside(path, folder):
    path, folder = os.path.realpath(path), os.path.realpath(folder)
    return os.path.commonpath([path, folder]) == folder


def parse_args(argv):
    if len(argv) != 4:
        return None
    got = {}
    for key, value in (argv[0:2], argv[2:4]):
        if key not in ("--data", "--out") or key in got:
            return None
        got[key] = value
    return got["--data"], got["--out"]


def check_python():
    return platform.python_version() == PYTHON


def check_packages():
    for name, version in PINS:
        try:
            if importlib.metadata.version(name) != version:
                return False
        except importlib.metadata.PackageNotFoundError:
            return False
    return True


def model_bytes():
    try:
        return base64.b64decode("".join(MODEL_B64), validate=True)
    except Exception:
        return None


def check_model():
    b = model_bytes()
    settings = [text for rel, _h, text in FILES if rel == "models/core_v1.txt"]
    return (b is not None and sha(b) == MODEL_SHA and len(settings) == 1
            and sha(settings[0].encode("utf-8")) == SETTINGS_SHA)


def records_ok(path):
    """The tracking's records (lines of three ':'-separated parts, as read_atd reads them) are exactly 1 to 199,319."""
    seen, n = bytearray(N_FRAMES + 1), 0
    with open(path) as f:
        for line in f:
            parts = line.rstrip("\n").split(":")
            if len(parts) != 3:
                continue
            try:
                i = int(parts[0])
            except ValueError:
                return False
            if not 1 <= i <= N_FRAMES or seen[i]:
                return False
            seen[i] = 1
            n += 1
    return n == N_FRAMES


def passes(fn):
    try:
        return bool(fn())
    except Exception:
        return False


def remove_tree(root):
    """Remove the temporary code folder file by file with absolute paths (so an audit sees where each removal is)."""
    try:
        for here, dirs, files in os.walk(root, topdown=False):
            for name in files:
                os.remove(os.path.join(here, name))
            for name in dirs:
                os.rmdir(os.path.join(here, name))
        os.rmdir(root)
    except OSError:
        pass


def write_tree(root):
    """The embedded files at their places in a code folder of their own; returns that folder."""
    code = os.path.join(root, "code")
    for rel, _h, text in FILES:
        path = os.path.join(code, *rel.split("/"))
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "wb") as f:
            f.write(text.encode("utf-8"))
    with open(os.path.join(code, "models", "core_v1.joblib"), "wb") as f:
        f.write(model_bytes())
    return code


# ------------------------------------------------------------------------------------------------ the checks
def check_sources():
    hashes = {rel: h for rel, h, _text in FILES}
    return (all(sha(text.encode("utf-8")) == h for _rel, h, text in FILES)
            and hashes.get("dead_ball_v1_1.py") == DBV_SHA and hashes.get("possession_v3_1.py") == P16_SHA)


def learned_bytes(name="LEARNED_B64"):
    try:
        return base64.b64decode("".join(globals()[name]), validate=True)
    except Exception:
        return None


