FILES.append(('alignment_stats.py', '91a58962dcbe5e2338f82921ad15f2dcaeff35bfb5774d250adc004143ce7820', r'''"""Shared statistics for the five-minute alignment study (report 0012). Pure functions on arrays; no file access.

pair()        each switch with the nearest event (optionally of the same team) within a window
stats()       n found, median, 10th/90th percentile, robust spread = 1.4826 x MAD (seconds)
shift_null()  the observed spread as a percentile of spreads after circular shifts of the SWITCHES (events fixed)
split()       best candidate on the earliest switches, every candidate's spread on the latest ones
"""

import numpy as np

FPS = 25
NULL_N, NULL_SEED, NULL_LO_S, NULL_HI_S = 300, 0, 20.0, 280.0


def pair(switches, events, window_frames, switch_teams=None, event_teams=None):
    """Lag (switch - event, frames) per switch, or None. Team-matched when both team arrays are given."""
    ev = np.asarray(events, float)
    et = None if event_teams is None else np.asarray(event_teams)
    groups = {}
    out = []
    for i, s in enumerate(switches):
        key = None if et is None else switch_teams[i]
        if key not in groups:
            groups[key] = np.sort(ev if et is None else ev[et == key])
        cand = groups[key]
        if len(cand) == 0:
            out.append(None); continue
        k = int(np.searchsorted(cand, s))            # cand[k-1] < s <= cand[k]
        best = None
        for j in (k - 1, k):                         # the earlier neighbour first: ties go to the earlier event
            if 0 <= j < len(cand) and (best is None or abs(cand[j] - s) < abs(best - s)):
                best = cand[j]
        out.append(float(s - best) if abs(s - best) <= window_frames else None)
    return out


def spread_of(lags_s):
    x = np.asarray([v for v in lags_s if v is not None], float)
    return float(1.4826 * np.median(np.abs(x - np.median(x)))) if len(x) >= 2 else float("nan")


def stats(lags_frames):
    x = np.asarray([v for v in lags_frames if v is not None], float) / FPS
    if not len(x):
        return dict(n=0, median=float("nan"), p10=float("nan"), p90=float("nan"), spread=float("nan"))
    return dict(n=len(x), median=float(np.median(x)), p10=float(np.percentile(x, 10)),
                p90=float(np.percentile(x, 90)), spread=spread_of(x))


def shift_null(switches, events, window_frames, win_lo, win_hi, switch_teams=None, event_teams=None,
               n=NULL_N, seed=NULL_SEED):
    """Percentile (0-100) of the observed spread among spreads after circular shifts of the switch times."""
    observed = stats(pair(switches, events, window_frames, switch_teams, event_teams))["spread"]
    rng = np.random.default_rng(seed)
    length = win_hi - win_lo + 1
    offs = rng.uniform(NULL_LO_S * FPS, NULL_HI_S * FPS, n)
    null = []
    for o in offs:
        sw = [win_lo + ((s - win_lo + int(round(o))) % length) for s in switches]
        null.append(stats(pair(sw, events, window_frames, switch_teams, event_teams))["spread"])
    null = np.array([v for v in null if np.isfinite(v)])
    if not np.isfinite(observed) or not len(null):
        return float("nan")
    return float(100.0 * np.mean(null <= observed))


def split(switches, candidates, window_frames, switch_teams=None, k=6):
    """candidates: {name: (event_frames, event_teams or None)}. Returns (best name on the first k, {name: spread on last k})."""
    order = np.argsort(switches)
    first, last = order[:k], order[-k:]

    def spread_on(idx, ev, et):
        sw = [switches[i] for i in idx]
        st = None if switch_teams is None else [switch_teams[i] for i in idx]
        return stats(pair(sw, ev, window_frames, st, et))["spread"]
    early = {nm: spread_on(first, ev, et) for nm, (ev, et) in candidates.items()}
    finite = {nm: v for nm, v in early.items() if np.isfinite(v)}
    best = min(finite, key=lambda nm: (finite[nm], nm)) if finite else None
    return best, {nm: spread_on(last, ev, et) for nm, (ev, et) in candidates.items()}
'''))
