        w = csv.writer(f)
        w.writerow(["kind", "frame", "onset_s", "duration_s", "freq_hz", "strength"])
        for e in whistles:
            w.writerow(["whistle", "%.3f" % ((t0 + e["onset"]) * FPS), "%.3f" % (t0 + e["onset"]), "%.3f" % e["duration"],
                        "%.1f" % e["freq"], "%.2f" % e["prominence"]])
        for e in kicks:
            w.writerow(["kick", "%.3f" % ((t0 + e["onset"]) * FPS), "%.3f" % (t0 + e["onset"]), "", "", "%.2f" % e["strength"]])
