    for d in ds:
        near = onsets[(onsets >= d / FPS - 3) & (onsets <= d / FPS + 3)] if len(onsets) else []
        log.numbers("   dead start at video frame %d: whistle onsets within 3 s (key minus onset, s): %s"
                    % (d, " ".join("%+.3f" % (d / FPS - o) for o in near) or "none"))
    log.verdict("VERDICT V2: %d of %d dead starts have a whistle onset from 1.5 s before to 0.5 s after the key's switch"
                % (hits, len(ds)))
    if args.full:
        log.verdict("VERDICT V3: %s whole-match whistle count between 30 and 200" % ("PASS" if 30 <= len(whistles) <= 200
                                                                                     else "FAIL"))
    else:
        log.verdict("VERDICT V3: not checked (run with --full)")
