def grid_table(g):
    rows = ["  w  sigma_in  measured noise (cm)  median reading (s)  kicks detected  impulses per free-run minute"]
    for w in W_GRID:
        for s in S_GRID:
            c = g[(w, s)]
            rows.append("%3d  %8.2f  %19.2f  %18.4f  %10d of %d  %12.2f" % (w, s, 100 * c["noise"], c["reading"],
                                                                          c["detected"], N_KICK_GRID, c["false_rate"]))
    return rows


def public():
    import time
    import warnings
    import harness
    t0 = time.time()
    lines = []

    def out(s=""):
        print(s, flush=True)
        lines.append(s)
    out("REPORT 0055: BALL PHYSICS PROBE, PUBLIC PART (7 DFL matches, regime D, descriptive) AND THE GRID")
    g = grid()
    g1 = check_grid(g)
