                        f(None if s["noise_p90"] is None else 100 * s["noise_p90"]), "%d" % s["impulses"],
                        f(s["rate"]), f(s["near"]), f(s["rise_med"]), f(s["rise_p90"]), "%d" % s["n_rise"],
