import argparse
import os
import sys
import time

import numpy as np

HERE = os.path.dirname(os.path.abspath(__file__))
REPO = os.path.join(HERE, "more-than-a-hack-2027")
if not os.path.isdir(REPO):
    REPO = os.environ.get("MTAH_REPO", REPO)
