import possession_metrics as pm  # noqa: E402

FPS = 25
H, A, D = 0, 1, 2
GT_PATH = os.path.join(REPO, "evaluation", "gt", "BAR-ATH_possession_gt_public.csv")
PUBLIC_WINDOW = (11185, 18684)


def score(gt, pred):
    runs = pm.valid_runs(gt)
    sp = pm.spell_scores(gt, pm.fill_abstentions(pred, runs), runs)
    return sp["mean_f1"], sp["per_iou"][0.3]["f1"], sp["per_iou"][0.7]["f1"], sp["n_pred"], sp["n_gt"]


def segs_of(a):
    ch = np.flatnonzero(a[1:] != a[:-1]) + 1
    st = np.r_[0, ch]; en = np.r_[ch, len(a)]
    return [(int(s), int(e), int(a[s])) for s, e in zip(st, en)]


def rebuild(codes, bounds, T):
    out = np.empty(T, np.int8); prev = 0
    for c, b in zip(codes, list(bounds) + [T]):
        out[prev:b] = c; prev = b
    return out


def move_boundaries(a, sd_dead, sd_flip, rng, shift_dead=0.0, shift_flip=0.0):
    """Move every internal boundary: those next to a dead stretch by N(shift_dead, sd_dead) frames, team changes by N(shift_flip, sd_flip)."""
    segs = segs_of(a); T = len(a)
    codes = [c for _, _, c in segs]
    b = np.array([e for _, e, _ in segs[:-1]], float)
    kinds = np.array([(codes[i] == D or codes[i + 1] == D) for i in range(len(b))])
    new = b + np.where(kinds, shift_dead + rng.normal(0, sd_dead, len(b)), shift_flip + rng.normal(0, sd_flip, len(b)))
    new = np.clip(np.round(new), 1, T - 1)
    new = np.sort(new)
    for i in range(len(new)):                               # strictly increasing, room for the rest
        lo = (new[i - 1] + 1) if i else 1
        new[i] = max(new[i], lo)
    for i in range(len(new) - 1, -1, -1):
        hi = (new[i + 1] - 1) if i < len(new) - 1 else T - 1
        new[i] = min(new[i], hi)
    return rebuild(codes, [int(x) for x in new], T)


def miss_boundaries(a, q, rng):
    segs = segs_of(a); T = len(a)
    codes = [c for _, _, c in segs]
    for i in range(1, len(codes)):
        if rng.random() < q:
            codes[i] = codes[i - 1]
    return rebuild(codes, [e for _, e, _ in segs[:-1]], T)


def flip_teams(a, w, rng):
    segs = segs_of(a); T = len(a)
    codes = [(1 - c if (c in (H, A) and rng.random() < w) else c) for _, _, c in segs]
    return rebuild(codes, [e for _, e, _ in segs[:-1]], T)


def flicker(a, per_min, dur, rng):
    out = a.copy(); T = len(a)
    for _ in range(int(rng.poisson(per_min * T / FPS / 60.0))):
        t = int(rng.integers(0, T))
        if out[t] in (H, A):
            out[t:t + dur] = 1 - out[t]
    return out


def mc(gt, fn, draws, seed=0):
    rng = np.random.default_rng(seed)
    res = np.array([score(gt, fn(rng)) for _ in range(draws)])
    return res[:, 0].mean(), np.percentile(res[:, 0], 10), np.percentile(res[:, 0], 90), res[:, 1].mean(), res[:, 2].mean(), res[:, 3].mean()


def tolerance_table(lengths_s):
    print("   how far one possession can be shifted (both edges the same way) and still count, by possession length")
    print("   %-26s %-12s %-12s %-12s" % ("length of the possession", "at IoU 0.3", "at IoU 0.5", "at IoU 0.7"))
    for L in (0.76, 2.0, 4.0, 7.6, 14.2, 25.0):
        print("   %-26s %-12s %-12s %-12s" % ("%.2f s" % L, *["%.2f s" % (L * (1 - t) / (1 + t)) for t in (0.3, 0.5, 0.7)]))
    ls = np.array(lengths_s)
    print("   in this data: %d possessions, median %.1f s; share shorter than 4 s: %.0f%%; a 1 s shift survives IoU 0.5 for %.0f%% of them, IoU 0.7 for %.0f%%"
          % (len(ls), np.median(ls), 100 * np.mean(ls < 4), 100 * np.mean(ls * (1 - 0.5) / (1 + 0.5) >= 1.0), 100 * np.mean(ls * (1 - 0.7) / (1 + 0.7) >= 1.0)))


def tables(gt, draws, label):
    print("\n" + "=" * 100 + "\n%s\n" % label + "=" * 100)
    sp = [(e - s) / FPS for s, e, c in segs_of(gt) if c in (H, A)]
    tolerance_table(sp)
    base = score(gt, gt)
    print("\n   a perfect answer scores %.3f (%d possessions)" % (base[0], base[4]))
    SD = (0.1, 0.25, 0.5, 0.75, 1.0, 1.5, 2.0, 3.0)
    print("\n   1. RANDOM TIMING ERROR on the edges (every edge moved by a random amount, standard deviation in seconds); teams and segmentation perfect")
    print("   %-10s | %-26s | %-26s | %-26s" % ("sd (s)", "all edges", "only dead-ball edges", "only team-change edges"))
    print("   %-10s | %-26s | %-26s | %-26s" % ("", "spellF1 [10th-90th]", "spellF1 [10th-90th]", "spellF1 [10th-90th]"))
    for sd in SD:
        a = mc(gt, lambda r: move_boundaries(gt, sd * FPS, sd * FPS, r), draws)
        b = mc(gt, lambda r: move_boundaries(gt, sd * FPS, 0.0, r), draws)
        c = mc(gt, lambda r: move_boundaries(gt, 0.0, sd * FPS, r), draws)
        print("   %-10.2f | %.3f [%.3f-%.3f]        | %.3f [%.3f-%.3f]        | %.3f [%.3f-%.3f]" % (sd, a[0], a[1], a[2], b[0], b[1], b[2], c[0], c[1], c[2]))
    print("\n   2. CONSTANT LAG on all edges (every edge late by the same time); a negative lag means early")
    print("   %-10s %-12s %-12s %-12s" % ("lag (s)", "spellF1", "at IoU 0.3", "at IoU 0.7"))
    for lag in (-3, -2, -1, -0.5, -0.25, 0.25, 0.5, 1, 2, 3):
        r = mc(gt, lambda rng: move_boundaries(gt, 0.0, 0.0, rng, lag * FPS, lag * FPS), 1)
        print("   %-10.2f %-12.3f %-12.3f %-12.3f" % (lag, r[0], r[3], r[4]))
    print("\n   3. MISSED EDGES (a share of the edges is not detected, so two possessions or a stoppage merge); timing perfect")
    for q in (0.05, 0.1, 0.2, 0.3, 0.5):
        r = mc(gt, lambda rng: miss_boundaries(gt, q, rng), draws)
        print("   %2.0f%% missed:   spellF1 %.3f [%.3f-%.3f]" % (100 * q, r[0], r[1], r[2]))
    print("\n   4. WRONG TEAM (a share of possessions is given to the other team); timing perfect")
    for w in (0.05, 0.1, 0.2, 0.3):
        r = mc(gt, lambda rng: flip_teams(gt, w, rng), draws)
        print("   %2.0f%% wrong:    spellF1 %.3f [%.3f-%.3f]" % (100 * w, r[0], r[1], r[2]))
    print("\n   5. FLICKER (false 1-second flips to the other team, a number per minute); everything else perfect")
    for rate in (0.5, 1, 2, 4):
        r = mc(gt, lambda rng: flicker(gt, rate, FPS, rng), draws)
        print("   %.1f per minute: spellF1 %.3f [%.3f-%.3f]  (%.0f possessions predicted against %d)" % (rate, r[0], r[1], r[2], r[5], base[4]))
    print("\n   6. COMBINED: timing error on all edges, plus missed edges, plus 5% wrong team")
    print("   %-12s %-14s %-14s %-14s" % ("sd (s)", "0% missed", "10% missed", "20% missed"))
    for sd in (0.5, 1.0, 2.0):
        cells = []
        for q in (0.0, 0.1, 0.2):
            r = mc(gt, lambda rng: flip_teams(miss_boundaries(move_boundaries(gt, sd * FPS, sd * FPS, rng), q, rng), 0.05, rng), draws)
            cells.append("%.3f" % r[0])
        print("   %-12.1f %-14s %-14s %-14s" % (sd, *cells))


def load_key():
    import csv
    labels = []
    with open(GT_PATH) as f:
        r = csv.reader(f); next(r)
        for row in r: labels.append(row[1].strip().upper())
    a, b = PUBLIC_WINDOW
    return np.array([{"H": H, "A": A, "D": D}[x] for x in labels[a:b + 1]], np.int8)


def part_b(draws):
    sys.path.insert(0, HERE)
    import external_harness_v2 as eh
    import dead_ball_lab as lab1
    ids = eh.available_ids()
    M = lab1.load_all(ids)
    for S_merge in (2.0, 3.0):
        rows = {}
        for mid, m in M.items():
            gt = eh.join([eh.coarsen(l, S_merge) for l in m["labs"]])
            for sd in (0.25, 0.5, 1.0, 2.0, 3.0):
                rows.setdefault(("sd", sd), []).append(mc(gt, lambda r: move_boundaries(gt, sd * FPS, sd * FPS, r), draws)[0])
                rows.setdefault(("sd_dead", sd), []).append(mc(gt, lambda r: move_boundaries(gt, sd * FPS, 0.0, r), draws)[0])
                rows.setdefault(("sd_flip", sd), []).append(mc(gt, lambda r: move_boundaries(gt, 0.0, sd * FPS, r), draws)[0])
            for q in (0.1, 0.2):
                rows.setdefault(("miss", q), []).append(mc(gt, lambda r: miss_boundaries(gt, q, r), draws)[0])
            for w in (0.05, 0.1):
                rows.setdefault(("wrong", w), []).append(mc(gt, lambda r: flip_teams(gt, w, r), draws)[0])
            for rate in (1, 4):
                rows.setdefault(("flick", rate), []).append(mc(gt, lambda r: flicker(gt, rate, FPS, r), draws)[0])
        n_poss = np.mean([len([1 for s, e, c in segs_of(eh.join([eh.coarsen(l, S_merge) for l in m["labs"]])) if c in (H, A)]) for m in M.values()])
        print("\n" + "=" * 100 + "\nPART B. SEVEN PUBLIC MATCHES, possessions shorter than %.0f s merged away (about %.0f possessions per match), mean over matches\n" % (S_merge, n_poss) + "=" * 100)
        print("   random timing error on all edges (sd in s):   " + "   ".join("%.2f s: %.3f" % (sd, np.mean(rows[("sd", sd)])) for sd in (0.25, 0.5, 1.0, 2.0, 3.0)))
        print("   random timing error on dead-ball edges only:   " + "   ".join("%.2f s: %.3f" % (sd, np.mean(rows[("sd_dead", sd)])) for sd in (0.25, 0.5, 1.0, 2.0, 3.0)))
        print("   random timing error on team-change edges only: " + "   ".join("%.2f s: %.3f" % (sd, np.mean(rows[("sd_flip", sd)])) for sd in (0.25, 0.5, 1.0, 2.0, 3.0)))
        print("   missed edges:   " + "   ".join("%.0f%%: %.3f" % (100 * q, np.mean(rows[("miss", q)])) for q in (0.1, 0.2)))
        print("   wrong team:     " + "   ".join("%.0f%%: %.3f" % (100 * w, np.mean(rows[("wrong", w)])) for w in (0.05, 0.1)))
        print("   flicker:        " + "   ".join("%d per min: %.3f" % (r_, np.mean(rows[("flick", r_)])) for r_ in (1, 4)))


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--dfl", action="store_true")
    ap.add_argument("--draws", type=int, default=300)
    args = ap.parse_args()
    t0 = time.time()
    gt = load_key()
    tables(gt, args.draws, "PART A. THE COMPETITION'S PUBLIC 5 MINUTES (the real key: 17 possessions, 4 dead stretches)")
