def combo_logE(fs, lo, use_sp, use_p, w=W_SP, m=M_P):
    """K1's emission: v1.2's, with P's removal of fleeting team evidence and SP's evidence on live missing frames."""
    logE = npz.persistence_logE(fs, m) if use_p else sp.dwell_logE(fs, *p12.ADOPTED)
    if use_sp:
        miss = ~np.asarray(fs["ball_visible"], bool) & ~np.asarray(fs["dead"], bool)
        logE[miss, H] += w * lo[miss] / 2
        logE[miss, A] -= w * lo[miss] / 2
    return logE


def decode_combo(fs, lo, config, lo_l=None, w_l=None):
    if config == "V":
        return np.asarray(p12.decode_half(fs), np.int8)
    ch = CHANGES[config]
    if "L" in ch:
        logE = le.learned_logE(fs, lo_l, w_l if w_l is not None else W_L)
        if "SP" in ch:
            miss = ~np.asarray(fs["ball_visible"], bool) & ~np.asarray(fs["dead"], bool)
            logE[miss, H] += W_SP * lo[miss] / 2
            logE[miss, A] -= W_SP * lo[miss] / 2
        return l1a.dec.viterbi(logE, 1 / sp.EPS_K).astype(np.int8)
    return l1a.dec.viterbi(combo_logE(fs, lo, "SP" in ch, "P" in ch), 1 / sp.EPS_K).astype(np.int8)


