# ------------------------------------------------------------------------------------------------ the five lines
def iou_match(true_st, pred_st, thr):
    """One-to-one greedy matching by IoU (largest first) needing IoU >= thr. [(true index, predicted index)]."""
    pairs = []
    for i, (ts, te) in enumerate(true_st):
        for j, (ps, pe) in enumerate(pred_st):
            ov = min(te, pe) - max(ts, ps)
            if ov > 0:
                iou = ov / (max(te, pe) - min(ts, ps))
                if iou >= thr:
                    pairs.append((-iou, i, j))
