    onset = {d["index"]: int(round(float(d["onset_s"]) * FPS)) for d in dets}
    stop = [i for i in sorted(labels) if labels[i] == "stop" and i in onset]
    rest = [i for i in sorted(labels) if labels[i] in ("restart", "other") and i in onset]
