def main(argv=None):
    if argv:
        sys.exit("core_window_offsets: no arguments are taken")
    if not os.environ.get("MTAH_DATA_DIR"):
        sys.exit("core_window_offsets: MTAH_DATA_DIR is not set. Run with ~/Desktop/Bar/code/run_checked.sh "
                 "core_window_offsets.py")
