def dynamic_features(S, vis):
    T = S["T"]
    bx = np.where(vis, S["ball"][:, 0], np.nan); by = np.where(vis, S["ball"][:, 1], np.nan)
    bs = np.full(T, np.nan); bs[1:] = np.hypot(np.diff(bx), np.diff(by)) * FPS
    bs1 = roll(bs, 25)
    (xmin, xmax), (ymin, ymax) = S["bounds"]
    dline = np.clip(np.minimum.reduce([bx - xmin, xmax - bx, by - ymin, ymax - by]), -5, 20)
    d1 = np.fmin(np.where(vis, S["dh0"], np.nan), np.where(vis, S["da0"], np.nan))
    idx = np.where(vis, np.arange(T), -1); last = np.maximum.accumulate(idx)
    gap = np.minimum(np.where(last >= 0, np.arange(T) - last, 750), 750) / 250.0
    cols = [np.log1p(S["pm1"]), np.log1p(S["pm3"]), S["slow"], np.log1p(S["fast"]), vis.astype(float), gap,
            np.log1p(np.nan_to_num(bs1, nan=0.0)), (~np.isnan(bs1)).astype(float),
            np.nan_to_num(dline, nan=10.0) / 10.0, np.nan_to_num(np.clip(d1, 0, 30), nan=3.0) / 10.0]
    return np.nan_to_num(np.column_stack(cols), nan=0.0)


def fit_logreg(X, y, l2=1.0, iters=40):
    mu, sd = X.mean(0), X.std(0) + 1e-6
    Z = np.column_stack([np.ones(len(X)), (X - mu) / sd]); w = np.zeros(Z.shape[1])
    reg = l2 * np.eye(Z.shape[1]); reg[0, 0] = 0
    for _ in range(iters):
        p = 1 / (1 + np.exp(-np.clip(Z @ w, -30, 30)))
        g = Z.T @ (p - y) + reg @ w
        Hs = (Z.T * (p * (1 - p) + 1e-6)) @ Z + reg
        step = np.linalg.solve(Hs, g); w -= step
        if np.linalg.norm(step) < 1e-6:
            break
    return mu, sd, w


def proba(model, X):
    mu, sd, w = model
    return 1 / (1 + np.exp(-np.clip(np.column_stack([np.ones(len(X)), (X - mu) / sd]) @ w, -30, 30)))


def viterbi2(logE, eps):
    T = len(logE); stay, sw = np.log(1 - eps), np.log(eps)
    d0, d1 = logE[0, 0], logE[0, 1]; back = np.zeros((T, 2), np.int8)
    for t in range(1, T):
        if d0 + stay >= d1 + sw: n0, b0 = d0 + stay, 0
        else: n0, b0 = d1 + sw, 1
        if d1 + stay >= d0 + sw: n1, b1 = d1 + stay, 1
        else: n1, b1 = d0 + sw, 0
        d0, d1 = n0 + logE[t, 0], n1 + logE[t, 1]; back[t, 0], back[t, 1] = b0, b1
    path = np.empty(T, np.int8); path[-1] = 0 if d0 >= d1 else 1
    for t in range(T - 1, 0, -1):
        path[t - 1] = back[t, path[t]]
    return path


def smooth_dead(p, weight, eps):
    p = np.clip(p, 1e-4, 1 - 1e-4)
    return viterbi2(weight * np.column_stack([np.log(1 - p), np.log(p)]), eps) == 1


def dead_metrics(gt_parts, dead_parts):
    gt = eh.join(gt_parts)
    pred = eh.join([np.where(d, D, H).astype(np.int8) for d in dead_parts])
    s = eh.score(gt, pred)
    return s["ad"], s["df1"]


def code_dead(pred_codes):
    return pred_codes == D


def load_all(ids):
    M = {}
    for mid in ids:
        t0 = time.time()
        try:
            halves = eh.load_match(mid)
        except BaseException as e:
            print("   skipping %s: %s" % (mid, str(e)[:80])); continue
        feats = [eh.base_features(h) for h in halves]
        stat = [static_features(h) for h in halves]
        M[mid] = dict(labs=[h["lab"] for h in halves], feats=feats, stat=stat,
                      dummy=[{"lab": h["lab"]} for h in halves])
        print("   loaded %s [%.0f s]" % (mid, time.time() - t0), flush=True)
    return M


def training_set(M, names, seeds=(0, 1), step=5):
    Xs, ys = [], []
    for mid in names:
        m = M[mid]
        for s in seeds:
            vis = eh.make_vis(m["dummy"], m["feats"], s)
            for lab, S, v in zip(m["labs"], m["stat"], vis):
                X = dynamic_features(S, v)
                Xs.append(X[::step]); ys.append((lab == D).astype(float)[::step])
    return np.vstack(Xs), np.concatenate(ys)


def leave_one_match_out(M):
    names = list(M)
    rows = {}
