# ------------------------------------------------------------------------------------------------ D2 router
def route(stops, ev_by_half):
    """(v1.1 stoppages, rows) in time order: each start moves to the nearest ES3 event of its block in
    [s - 6 s, s + 2 s] (a tie to the earlier) + 3 frames, if that start is <= e - 2 s and >= the previous end + 1."""
    order = sorted(range(len(stops)), key=lambda i: (stops[i][1], i))
    out, rows, e_prev = [], [], None
    for i in order:
        h, s, e = stops[i]
        ev = np.asarray(ev_by_half[h - 1], int)
        win = ev[(ev >= s - BEFORE) & (ev <= s + AFTER)]
        row = dict(core=s, event=None, start=s, status="no event")
        if len(win):
            d = np.abs(win - s)
            x = int(win[d == d.min()].min())
            new = x + cb.ROUTER_ADD
            row["event"] = x
            if new > e - MIN_LEFT:
                row["status"] = "skipped end"
            elif e_prev is not None and new < e_prev + 1:
                row["status"] = "skipped previous end"
            else:
                row.update(start=new, status="moved" if new != s else "routed in place")
        out.append((h, row["start"], e))
        rows.append(row)
        e_prev = e
    return out, rows


def moves_of(rows):
    return [r["start"] - r["core"] for r in rows if r["status"] == "moved"]


def largest(moves):
    """The move with the largest |move|, a tie to the earlier; 0 when none."""
    best = 0
    for m in moves:
        if abs(m) > abs(best):
            best = m
    return best


