FILES.append(('deadball_metrics.py', '75a1f3afba5fb82aceb4b5d47105fe96b096370cabd7ea8abc4821cf638d7c00', r'''"""Dead-ball yardstick (report 0014 Part 1.1): pure functions on a predicted and a true boolean dead array per half.

Definitions (claude_reports/0014_dead_ball_yardstick_and_signals.md, written before this file):
  stoppage      a maximal run of dead frames [s, e)
  frame         accuracy; precision, recall, F1 for dead; recall on frames inside true stoppages of at least 10 s
  stoppage      true and predicted stoppages of at least 2 s only; one-to-one greedy matching by IoU, a match needs
                IoU >= 0.5; precision, recall, F1; recall on true stoppages of at least 10 s; FALSE (unmatched
                predicted), SPLITS (a true one overlapped by 2+ predicted), MERGES (a predicted one overlapping 2+ true)
  edge shifts   matched pairs, predicted - true in seconds, start and end; percentiles and shares within 0.5 / 1 / 2 s,
                overall, by true length class and (when types are given) by type
half_counts() works on one half; pool() adds halves together; summary() turns the pooled counts into the metrics.
"""

import numpy as np

FPS = 25
MIN_STOP, LONG_STOP = 2 * FPS, 10 * FPS
LENGTH_CLASSES = (("2-10 s", 2, 10), ("10-20 s", 10, 20), ("20-30 s", 20, 30), ("30+ s", 30, np.inf))
PCTS = (10, 25, 50, 75, 90)
WITHIN_S = (0.5, 1.0, 2.0)


def stoppages(dead):
    m = np.r_[False, np.asarray(dead, bool), False]
    e = np.flatnonzero(np.diff(m.astype(np.int8)))
    return [(int(a), int(b)) for a, b in zip(e[::2], e[1::2])]


def match(true_st, pred_st):
    """One-to-one greedy matching by IoU (needs 2 x overlap >= union). Returns [(true index, predicted index)]."""
    pairs = []
    for i, (ts, te) in enumerate(true_st):
        for j, (ps, pe) in enumerate(pred_st):
            ov = min(te, pe) - max(ts, ps)
            if ov <= 0:
                continue
            un = max(te, pe) - min(ts, ps)
            if 2 * ov >= un:
                pairs.append((-ov / un, ts, ps, i, j))
    pairs.sort()
    used_i, used_j, out = set(), set(), []
    for _, _, _, i, j in pairs:
        if i not in used_i and j not in used_j:
            used_i.add(i); used_j.add(j); out.append((i, j))
    return sorted(out)


def _overlaps(a, b):
    return min(a[1], b[1]) > max(a[0], b[0])


def half_counts(pred, true, types=None):
    """Counts and shift lists for one half. types: optional function (true end frame) -> type name."""
    pred, true = np.asarray(pred, bool), np.asarray(true, bool)
    assert pred.shape == true.shape
    tp = int(np.sum(pred & true)); fp = int(np.sum(pred & ~true)); fn = int(np.sum(~pred & true))
    long_mask = np.zeros(len(true), bool)
    for s, e in stoppages(true):
        if e - s >= LONG_STOP:
            long_mask[s:e] = True
    ts = [x for x in stoppages(true) if x[1] - x[0] >= MIN_STOP]
    ps = [x for x in stoppages(pred) if x[1] - x[0] >= MIN_STOP]
    m = match(ts, ps)
    mi = {i for i, _ in m}; mj = {j for _, j in m}
    shifts = []
    for i, j in m:
        (a, b), (c, d) = ts[i], ps[j]
        shifts.append(dict(start=(c - a) / FPS, end=(d - b) / FPS, length=(b - a) / FPS,
                           type=types(b) if types else None))
    return dict(n=len(true), tp=tp, fp=fp, fn=fn, long_true=int(long_mask.sum()), long_tp=int(np.sum(pred & long_mask)),
                n_true=len(ts), n_pred=len(ps), n_match=len(m),
                n_true_long=sum(1 for s, e in ts if e - s >= LONG_STOP),
                n_match_long=sum(1 for i in mi if ts[i][1] - ts[i][0] >= LONG_STOP),
                false=len(ps) - len(mj),
                splits=sum(1 for t in ts if sum(_overlaps(t, p) for p in ps) >= 2),
                merges=sum(1 for p in ps if sum(_overlaps(p, t) for t in ts) >= 2),
                shifts=shifts)


def pool(counts):
    out = {k: 0 for k in counts[0] if k != "shifts"}
    out["shifts"] = []
    for c in counts:
        for k, v in c.items():
            if k == "shifts":
                out["shifts"] += v
            else:
                out[k] += v
    return out


def _prf(tp, npred, ntrue):
    p = tp / npred if npred else 0.0
    r = tp / ntrue if ntrue else 0.0
    return p, r, (2 * p * r / (p + r) if p + r > 0 else 0.0)


def shift_stats(values):
    x = np.asarray(values, float)
    if not len(x):
        return dict(n=0)
    out = dict(n=len(x))
    for q in PCTS:
        out["p%d" % q] = float(np.percentile(x, q))
    for w in WITHIN_S:
        out["within_%g" % w] = float(np.mean(np.abs(x) <= w + 1e-9))
    return out


def summary(c):
    """The yardstick from pooled counts."""
    fp_, fr, ff = _prf(c["tp"], c["tp"] + c["fp"], c["tp"] + c["fn"])
    sp, sr, sf = _prf(c["n_match"], c["n_pred"], c["n_true"])
    out = dict(frame_accuracy=(c["n"] - c["fp"] - c["fn"]) / c["n"] if c["n"] else 0.0, frame_precision=fp_,
               frame_recall=fr, frame_f1=ff, frame_recall_long=c["long_tp"] / c["long_true"] if c["long_true"] else 0.0,
               stop_precision=sp, stop_recall=sr, stop_f1=sf,
               stop_recall_long=c["n_match_long"] / c["n_true_long"] if c["n_true_long"] else 0.0,
               n_true=c["n_true"], n_pred=c["n_pred"], n_match=c["n_match"], false=c["false"], splits=c["splits"],
               merges=c["merges"])
    sh = c["shifts"]
    for edge in ("start", "end"):
        out["shift_" + edge] = shift_stats([s[edge] for s in sh])
        out["shift_%s_by_length" % edge] = {nm: shift_stats([s[edge] for s in sh if lo <= s["length"] < hi])
                                            for nm, lo, hi in LENGTH_CLASSES}
        types = sorted({s["type"] for s in sh if s["type"] is not None})
        out["shift_%s_by_type" % edge] = {t: shift_stats([s[edge] for s in sh if s["type"] == t]) for t in types}
    return out


def evaluate(preds, trues, types=None):
    """preds, trues: lists of boolean arrays (one per half); types: optional list of per-half type functions."""
    return summary(pool([half_counts(p, t, types[k] if types else None) for k, (p, t) in enumerate(zip(preds, trues))]))
'''))
