WAV_REL = os.path.join("audio", "deadball_panels.wav")


# ------------------------------------------------------------------------------------------------ series
def smooth5(s):
    """Centred 5-frame mean ignoring NaN; NaN where all 5 are NaN and on the first and last 2 frames."""
    s = np.asarray(s, float)
    out = np.full(len(s), np.nan)
    if len(s) < 5:
        return out
    w = np.lib.stride_tricks.sliding_window_view(s, 5)
    n = np.isfinite(w).sum(axis=1)
    tot = np.nansum(w, axis=1)
    out[2:-2] = np.where(n > 0, tot / np.maximum(n, 1), np.nan)
    return out


def player_series(home, away):
    pl = np.concatenate([home, away], axis=1)
    sp = fm.speeds(pl)
    n = np.isfinite(sp).sum(axis=1)
    out = dict(median=smooth5(fm.median_speed(home, away)), count=np.isfinite(pl[..., 0]).sum(axis=1))
    for name, thr in (("share10", 1.0), ("share15", 1.5), ("share20", 2.0)):
        share = np.where(n > 0, (np.nan_to_num(sp, nan=np.inf) < thr).sum(axis=1) / np.maximum(n, 1), np.nan)
        out[name] = smooth5(share)
    return out


def signed_beyond(ball, length, width):
    """Positive: distance outside the rectangle [0, L] x [0, W]; zero or negative: minus the distance to the nearest line."""
    x, y = ball[:, 0], ball[:, 1]
    inside = -np.minimum(np.minimum(x, length - x), np.minimum(y, width - y))
    return np.where(inside <= 0, inside, ds.beyond(ball, length, width))


def ball_series(ball, home, away, length, width):
    pl = np.concatenate([home, away], axis=1)
    d = np.hypot(pl[..., 0] - ball[:, None, 0], pl[..., 1] - ball[:, None, 1])
    near = np.where(np.isfinite(d), d, np.inf).min(axis=1)
    return dict(present=np.isfinite(ball[:, 0]).astype(int), ball_speed=fm.speeds(ball),
                beyond=signed_beyond(ball, length, width), nearest=np.where(np.isfinite(near), near, np.nan))


def cut(a, i0, n):
    """a[i0:i0 + n], padded with NaN (or 0 for integers) where it runs off the array."""
    pad = 0 if np.issubdtype(np.asarray(a).dtype, np.integer) else np.nan
    out = np.full(n, pad, dtype=np.asarray(a).dtype if pad == 0 else float)
    lo, hi = max(i0, 0), min(i0 + n, len(a))
    if hi > lo:
        out[lo - i0:hi - i0] = a[lo:hi]
    return out


# ------------------------------------------------------------------------------------------------ marks
def parse_types(text):
    """{(stretch, "START"|"END"): type} from the 6th field of each marks line (the note, the 7th, is dropped)."""
    out = {}
    for line in text.splitlines():
        if not line.strip() or line.lstrip().startswith("#"):
            continue
        f = line.split(" | ")[:6]
        m = ds.LABEL.match(f[0]) if len(f) >= 5 else None
        if m:
            t = "".join(c for c in f[5].strip() if c.isprintable())[:TYPE_MAX] if len(f) >= 6 else ""
            out[(int(m.group(1)), m.group(2).upper())] = t
    return out


def edges(stretches):
    return [(n, kind, s if kind == "START" else e) for n, (s, e) in enumerate(stretches, 1) for kind in ("START", "END")]


# ------------------------------------------------------------------------------------------------ sound
def audio_span(keys):
    """(start, duration) in video seconds of the sound the panels need, with 2 s on each side."""
    t0 = round((min(keys) - HALF) / FPS - MARGIN_S, 3)
    return t0, round((max(keys) + HALF + 1) / FPS + MARGIN_S - t0, 3)


def column_frame(j, t0):
    return (t0 + (j * HOP + NFFT / 2) / FS) * FPS


def sound_panel(x, t0, key):
    """Band level and spectrogram strip of one panel, or None if the sound does not reach it."""
    total = (len(x) - NFFT) // HOP + 1
    jf = lambda f: int(np.ceil(((f / FPS - t0) * FS - NFFT / 2) / HOP))
    j_lo, j_hi = max(jf(key - HALF - 0.5), 0), min(jf(key + HALF + 0.5), total)
    if total <= 0 or j_hi <= j_lo:
        return None
    e_lo, e_hi = max(j_lo - MED_COLS, 0), min(j_hi + MED_COLS, total)
    view = np.lib.stride_tricks.sliding_window_view(x, NFFT)[::HOP][e_lo:e_hi]
    win = np.hanning(NFFT)
    mag = np.abs(np.fft.rfft(view.astype(float) * win, axis=1))
    band = 10 * np.log10(np.sum(mag[:, BAND_BINS[0]:BAND_BINS[1]] ** 2, axis=1) + 1e-20)
    rel = np.array([band[j - e_lo] - np.median(band[max(j - MED_COLS, e_lo) - e_lo:min(j + MED_COLS + 1, e_hi) - e_lo])
                    for j in range(j_lo, j_hi)])
    db = 20 * np.log10(mag[j_lo - e_lo:j_hi - e_lo, SPEC_BINS[0]:SPEC_BINS[1]] / (win.sum() / 2) + 1e-12)
    q = np.clip(np.round(2 * (db - SCALES["spec_db"][0])), 0, 255).astype(np.uint8)
    return dict(frame0=column_frame(j_lo, t0), step=HOP / FS * FPS, ncols=j_hi - j_lo, nbins=SPEC_BINS[1] - SPEC_BINS[0],
                bin0_hz=SPEC_BINS[0] * FS / NFFT, bin_hz=FS / NFFT, band=rel, spec=base64.b64encode(q.tobytes()).decode())


def get_audio(video, keys, wav):
    """((samples, t0), None) or (None, reason)."""
    if not video:
        return None, "no --video given"
    if not os.path.isfile(video):
        return None, "video file not found"
    if shutil.which("ffmpeg") is None:
        return None, "ffmpeg not found"
    t0, dur = audio_span(keys)
    try:
        ae.extract(video, wav, t0, dur)
        x, fs = ae.read_wav(wav)
    except (subprocess.CalledProcessError, OSError, EOFError, AssertionError):
        return None, "ffmpeg could not read the sound"
    if fs != FS or len(x) < NFFT:
        return None, "the video has no sound in the panels' time span"
    return (x, t0), None


