def cell_text(cell):
    return "merge %d s | regime %s%s" % (cell[0], cell[1], " | jittered ball" if len(cell) > 2 else "")


def s_text(setting):
    return "OFF" if setting == OFF else "d = %g, s = %g" % setting


# ------------------------------------------------------------------------------------------------ Z2 duel decoder
def duel_mask(dh, da, vis, d):
    """DUEL(d): the ball visible and both per-team nearest distances <= d (inclusive); NaN is never close; d = 0: none."""
    n = len(dh)
    if d <= 0:
        return np.zeros(n, bool)
    dh = np.nan_to_num(np.asarray(dh, float), nan=np.inf)
    da = np.nan_to_num(np.asarray(da, float), nan=np.inf)
    return np.asarray(vis, bool) & (dh <= d) & (da <= d)


