import os
import sys

import numpy as np

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
import ceiling  # noqa: E402  (segs_of)
import handover_switching_public as hs  # noqa: E402  (method_of: v1.0 for the proof; rate_of)
import harness  # noqa: E402  (matches, labels, run_method, paired, _score_match)
import l1a_measure as l1a  # noqa: E402  (boundaries)
import possession_budget_public as pb  # noqa: E402  (cell_data, oracle, truth_teams_on_mask, budget, anatomy, ...)
import possession_metrics as pm  # noqa: E402  (possession_spells; on the path through external_harness_v2)
import possession_v1_0 as pv  # noqa: E402  (C_DIGEST)
import short_possession_public as sp  # noqa: E402  (dwell, decode_dwell, method_of, adopt, _s_text, EPS_K)

H, A, D, FPS = harness.H, harness.A, harness.D, harness.FPS
PRIMARY = (2.0, "A")
MERGE1 = (1.0, "A")
A_CELLS = (PRIMARY, (3.0, "A"))
CELLS = (PRIMARY, (3.0, "A"), (2.0, "D"), (3.0, "D"), MERGE1)
R2, K2, W2 = (1.0, 1.5), (25, 37, 50, 75), (0.5, 1.0)
