    """Per frame: SHOWN, BALL_SPEED (|b(f+2) - b(f-2)| x 25/4), BEYOND (report 0098's signed_beyond), NEAREST player
    distance; NaN where the ball is not shown."""
    import explore_deadball_edges as xe
    b = np.where(np.asarray(shown, bool)[:, None], np.asarray(ball, float), np.nan)
    n = len(b)
