def run_length_at(lab, t, side):
    """Length (frames) of the constant run of lab that ends at t (side 'left': the run containing t - 1) or contains t."""
    lab = np.asarray(lab)
    i = t - 1 if side == "left" else t
    a = i
    while a > 0 and lab[a - 1] == lab[i]:
        a -= 1
    b = i + 1
    while b < len(lab) and lab[b] == lab[i]:
        b += 1
    return b - a


