# ------------------------------------------------------------------------------------------------ part 1
def entries(pred, k):
    """Frames where the prediction enters team k (from any other label, or at frame 0)."""
    pred = np.asarray(pred)
    is_k = pred == k
    return np.flatnonzero(is_k & np.r_[True, ~is_k[:-1]])


def start_classes(truth, pred):
    """[(s, e, k, class, p, pe)] per true possession: report 0045's class for a direct start (same-direction direct
    switches), the stated extension (entries into k) otherwise; p, pe = the matched predicted spell (None if MISSED)."""
    truth, pred = np.asarray(truth), np.asarray(pred)
    tb = {t: (f, to) for t, f, to in l1a.boundaries(truth)}
    pbs = l1a.boundaries(pred)
    runs = {a: b for a, b, _k in esp.spells_of(pred)}
    ent = {k: entries(pred, k) for k in (H, A)}
    out = []
