# ------------------------------------------------------------------ loading
def code_kind(c):
    defs = {k: str(v).lower() for k, v in (getattr(c, "definitions", None) or {}).items()}
    text = " ".join(defs.values()) + " " + str(getattr(c, "name", "")).lower()
    if "alive" in text or "dead" in text or "ballstatus" in text:
        return "ballstatus", defs
    if "home" in text or "away" in text or "possession" in text:
        return "possession", defs
    return "unknown", defs


def key_for(defs, word):
    for k, v in defs.items():
        if word in v:
            return k
    return None


def load_match(match_id):
    ds = IDSSEDataset(match_id=match_id)
    out = ds.get(match_id=match_id)
    positions, codes_a, codes_b = out[1], out[2], out[3]
    kind_a, defs_a = code_kind(next(iter(codes_a.values())))
    kind_b, defs_b = code_kind(next(iter(codes_b.values())))
    if kind_a == "ballstatus" and kind_b == "possession":
        status, poss, sdefs, pdefs = codes_a, codes_b, defs_a, defs_b
    elif kind_b == "ballstatus" and kind_a == "possession":
        status, poss, sdefs, pdefs = codes_b, codes_a, defs_b, defs_a
    else:
        raise SystemExit("Could not tell the possession and ball-status codes apart: %s %s" % (defs_a, defs_b))
    alive_k, dead_k = key_for(sdefs, "alive"), key_for(sdefs, "dead")
    home_k, away_k = key_for(pdefs, "home"), key_for(pdefs, "away")
    if None in (alive_k, dead_k, home_k, away_k):
        raise SystemExit("Unexpected code definitions: status=%s possession=%s" % (sdefs, pdefs))
    halves = []
    for half in ("firstHalf", "secondHalf"):
        st = np.asarray(status[half].code, dtype=float); po = np.asarray(poss[half].code, dtype=float)
        lab = np.full(len(st), D, np.int8)
        alive = st == alive_k
        lab[alive & (po == home_k)] = H
        lab[alive & (po == away_k)] = A
        unknown = alive & ~np.isin(po, [home_k, away_k])
        last = H
        for i in range(len(lab)):                       # an alive frame with no owner keeps the previous owner
            if lab[i] in (H, A): last = lab[i]
            elif unknown[i]: lab[i] = last
        T = len(lab)
        home = np.asarray(positions[half]["Home"].xy, float).reshape(T, -1, 2)
        away = np.asarray(positions[half]["Away"].xy, float).reshape(T, -1, 2)
        ball = np.asarray(positions[half]["Ball"].xy, float).reshape(T, 2)
        halves.append(dict(lab=lab, home=home, away=away, ball=ball, unknown=float(unknown.mean())))
