def coarsen(lab, min_s):
    """Merge live possessions shorter than min_s seconds into their neighbours (a touch is not control)."""
    if min_s <= 0:
        return lab.copy()
    minlen = int(min_s * FPS)
    segs = [[s, e, int(c)] for s, e, c in segments_of(lab)]
    while True:
        cand = [(e - s, i) for i, (s, e, c) in enumerate(segs) if c in (H, A) and e - s < minlen]
        if not cand:
            break
        _, i = min(cand)
        left = segs[i - 1] if i > 0 else None
        right = segs[i + 1] if i + 1 < len(segs) else None
        live = [n for n in (left, right) if n is not None and n[2] in (H, A)]
        if left is not None and right is not None and left[2] == right[2] and left[2] in (H, A):
            new = left[2]
        elif live:
            new = max(live, key=lambda n: n[1] - n[0])[2]
        else:
            new = D
        segs[i][2] = new
        merged = [segs[0]]
        for s in segs[1:]:
            if s[2] == merged[-1][2]:
                merged[-1][1] = s[1]
            else:
                merged.append(s)
        segs = merged
    out = np.empty(len(lab), np.int8)
    for s, e, c in segs:
        out[s:e] = c
    return out


