def predict(halves, feats, vis_list):
    """Baseline and decoder predictions (one array per half) for one dropout."""
    base_parts, dec_parts = [], []
    for half, (dh0, da0, pmean, _), vis in zip(halves, feats, vis_list):
        dh = np.where(vis, dh0, np.nan).astype(np.float32); da = np.where(vis, da0, np.nan).astype(np.float32)
        nearest = np.full(len(vis), -1, np.int8)
        ok = vis & ~np.isnan(dh) & ~np.isnan(da)
        nearest[ok] = np.where(dh[ok] <= da[ok], H, A)
        base_parts.append(smooth(nearest, 50))
        dec_parts.append(dec.decode_half(dh, da, vis, pmean).astype(np.int8))
    return join(base_parts), join(dec_parts)


def gt_stats(parts):
    poss = [b - a for p in parts for a, b, c in segments_of(p) if c in (H, A)]
    live_min = sum(int(np.sum((p == H) | (p == A))) for p in parts) / FPS / 60
    return len(poss), float(np.median(poss) / FPS), float(np.mean(poss) / FPS), len(poss) / live_min


def match_S(halves, targets=(7.56, 14.19), grid=(0, 0.5, 1, 1.5, 2, 3, 4, 5, 6)):
    best = None
    for S in grid:
        n, med, mean, per = gt_stats([coarsen(h["lab"], S) for h in halves])
        loss = abs(np.log(med / targets[0])) + abs(np.log(mean / targets[1]))
        if best is None or loss < best[0]:
            best = (loss, S)
    return best[1]


COMBOS = [(am, ast, eps) for am in (0.04, 0.08, 0.16) for ast in (0.08, 0.16, 0.32) for eps in (1 / 60, 1 / 100, 1 / 150, 1 / 250, 1 / 400)]


