RANKING_PATH = os.path.join(HERE, "dfl_candidate_ranking.json")


def top3_verdict(best, path=RANKING_PATH):
    import json
    if best is None or not os.path.isfile(path):
        return "NOT AVAILABLE"
    with open(path) as f:
        ranking = json.load(f)["merged_2s"]
    return "HOLDS" if best in [r["name"] for r in ranking[:3]] else "FAILS"


