# ------------------------------------------------------------------------------------------------ streams
def window_fits(y):
    """[(centre c, hinge fit on c-250 .. c+250 anchored at c)] for c = 250, 275, ... while c + 250 < len(y)."""
    return [(c, st.hinge(y, c - HW, c + HW, c)) for c in range(HW, len(y) - HW, STEP)]


def merge_events(raw, gap=MERGE_GAP):
    """Greedy from the kept event: keep the earliest, drop everything within `gap` frames after the last kept one."""
    out = []
    for t in sorted(int(x) for x in raw):
        if not out or t - out[-1] > gap:
            out.append(t)
    return np.array(out, int)


def hinge_events(fits, kind, side):
    raw = [f["tau"] for c, f in fits if st.is_clear(f, kind, side) and abs(f["tau"] - c) <= MID]
    return merge_events(raw)


def es3(ball, half_x=HALF_X, half_y=HALF_Y):
    """Frames t with the ball visible and >= 0.11 m beyond the rectangle at t, visible and not beyond at t - 1."""
    b = np.asarray(ball, float)
    fin = np.isfinite(b[:, 0]) & np.isfinite(b[:, 1])
    with np.errstate(invalid="ignore"):
        out = fin & (st.beyond_centred(b, half_x, half_y) >= st.BEYOND)
    return np.flatnonzero(out[1:] & fin[:-1] & ~out[:-1]) + 1


def candidate_mask(mine, sp_m, opp):
    """(T, n) bool: deadball_study.candidates' rule at every frame, vectorised (speed < 1.0 m/s over f-24 .. f, all
    finite; tracked at f; every tracked opponent more than 7 m away)."""
    T, n = sp_m.shape
    out = np.zeros((T, n), bool)
    f = np.arange(T)
    for i in range(n):
        p = mine[:, i]
        tracked = np.isfinite(p[:, 0]) & np.isfinite(p[:, 1])
        with np.errstate(invalid="ignore"):
            d = np.hypot(opp[:, :, 0] - p[:, None, 0], opp[:, :, 1] - p[:, None, 1])
            iso = np.where(np.isfinite(d), d, np.inf).min(axis=1) > st.ISOLATED
            slow = np.isfinite(sp_m[:, i]) & (sp_m[:, i] < st.SLOW)
        cs = np.r_[0, np.cumsum(slow)]
        cnt = np.zeros(T, int)
        cnt[24:] = cs[25:] - cs[:-25]
        out[:, i] = tracked & iso & (cnt == 25) & (f >= 24)
    return out


def es6(home, away, sp=None):
    """Taker run-up onsets (frames), players only; one event per player per 5 s; players pooled."""
    sph, spa = sp if sp is not None else st._speeds(home, away)
    events = []
    for mine, sp_m, opp in ((home, sph, away), (away, spa, home)):
        cand = candidate_mask(mine, sp_m, opp)
        for i in range(sp_m.shape[1]):
            v = sp_m[:, i]
            with np.errstate(invalid="ignore"):
                fast = np.flatnonzero(np.isfinite(v) & (v > st.RUN_START))
            cf = np.flatnonzero(cand[:, i])
            if not len(cf) or not len(fast):
                continue
            k = np.searchsorted(fast, cf, side="right")
            gs = np.unique(fast[k[k < len(fast)]])
            kept = []
            for g in gs:
                if np.nanmax(v[g:g + RUN_REACH + 1]) >= st.RUN and (not kept or g - kept[-1] > RUN_GAP):
                    kept.append(int(g))
            events += kept
    return np.array(sorted(events), int)


def player_streams(home, away):
    """{ES1, ES2, ES4, ES5, ES6: sorted event frames}; the players only (no ball argument)."""
    with warnings.catch_warnings():
        warnings.simplefilter("ignore")
        ser = st.series(home, away)
        fits = {name: window_fits(ser[name]) for name in ("s15", "B")}
    out = {s: hinge_events(fits[HINGE_DEF[s][0]], HINGE_DEF[s][1], HINGE_DEF[s][2]) for s in HINGE_DEF}
    out["ES6"] = es6(home, away)
    return out


# ------------------------------------------------------------------------------------------------ truth side (scoring only)
def flags_of(dead):
    """Start and end flags of dead stretches >= 10 s, those of shorter ones, and the long stretches."""
    T = len(dead)
    runs = dm.stoppages(dead)
    lng = [(s, e) for s, e in runs if e - s >= LONG]
    sht = [(s, e) for s, e in runs if e - s < LONG]
    return dict(start=[s for s, e in lng if s > 0], end=[e for s, e in lng if e < T],
                start_short=[s for s, e in sht if s > 0], end_short=[e for s, e in sht if e < T],
                start_stop=[(s, e) for s, e in lng if s > 0], end_stop=[(s, e) for s, e in lng if e < T])


def match_events(ev_s, fl_s, lo, hi):
    """One-to-one greedy matching by |offset| (ties: earlier flag, then earlier event). [(flag j, event i, offset s)]."""
    ev_s, fl_s = np.asarray(ev_s, float), np.asarray(fl_s, float)
    pairs = []
    for j, f in enumerate(fl_s):
        a, b = np.searchsorted(ev_s, f + lo - EPS, "left"), np.searchsorted(ev_s, f + hi + EPS, "right")
        for i in range(a, b):
            d = ev_s[i] - f
            if lo - EPS <= d <= hi + EPS:
                pairs.append((abs(d), j, i, d))
    pairs.sort()
    uj, ui, out = set(), set(), []
    for _ad, j, i, d in pairs:
        if j not in uj and i not in ui:
            uj.add(j); ui.add(i); out.append((j, i, d))
    return out


def half_score(events, flags, short_flags, dead, lo, hi):
    """Counts for one half. events: frames (int or float); dead: bool array (all dead stretches)."""
    ev = np.sort(np.asarray(events, float))
    ins = dead[np.clip(np.floor(ev).astype(int), 0, len(dead) - 1)] if len(ev) else np.zeros(0, bool)
    m = match_events(ev / FPS, np.asarray(flags, float) / FPS, lo, hi)
    mi = np.zeros(len(ev), bool)
    for _j, i, _d in m:
        mi[i] = True
    unm_out = ev[~mi & ~ins] / FPS
    sh = np.asarray(short_flags, float) / FPS
    near = sum(1 for x in unm_out if np.any((x - sh >= lo - EPS) & (x - sh <= hi + EPS)))
    return dict(n_flags=len(flags), n_match=len(m), n_ev=len(ev), n_inside=int(ins.sum()), n_out=int((~ins).sum()),
                n_match_out=int((mi & ~ins).sum()), n_false=int((~mi & ~ins).sum()), live=int((~dead).sum()),
                offsets=[d for _j, _i, d in m], pairs=sorted((j, d) for j, _i, d in m), near_short=near)


def pool(rows):
    out = {k: sum(r[k] for r in rows) for k in ("n_flags", "n_match", "n_ev", "n_inside", "n_out", "n_match_out",
                                                 "n_false", "live", "near_short")}
    out["offsets"] = [d for r in rows for d in r["offsets"]]
    out["halves"] = len(rows)
    return out


def rates(p):
    pr = p["n_match_out"] / p["n_out"] if p["n_out"] else float("nan")
    return dict(recall=p["n_match"] / p["n_flags"] if p["n_flags"] else float("nan"), precision=pr,
                false10=p["n_false"] / (p["live"] / (600.0 * FPS)) if p["live"] else float("nan"),
                inside=p["n_inside"] / p["n_ev"] if p["n_ev"] else float("nan"),
                per_half=p["n_ev"] / p["halves"] if p["halves"] else float("nan"))


def chance_sets(n_per_half, T_per_half, stream_no, regime_no, sets=CHANCE_SETS):
    """[set k: [half h: sorted uniform frames]] with default_rng((19, stream, regime, k, half))."""
    return [[np.sort(np.random.default_rng((19, stream_no, regime_no, k, h)).integers(0, T, n))
             for h, (n, T) in enumerate(zip(n_per_half, T_per_half))] for k in range(sets)]


def chance_stats(sets, halves_truth, side, lo, hi):
    rec, pre = [], []
    for s in sets:
        p = pool([half_score(ev, ht["flags"][side], ht["flags"][side + "_short"], ht["dead"], lo, hi)
                  for ev, ht in zip(s, halves_truth)])
        r = rates(p)
        rec.append(r["recall"]); pre.append(r["precision"])
    rec, pre = np.array(rec), np.array(pre)
    return dict(rec_mean=float(np.mean(rec)), rec_p95=float(np.percentile(rec, 95)),
                pre_mean=float(np.nanmean(pre)), pre_p95=float(np.nanpercentile(pre, 95)))


