def _first_in(ev, a, b):
    k = np.searchsorted(ev, a, "left")
    return int(ev[k]) if k < len(ev) and ev[k] <= b else None


def pair_stoppages(starts, es6_ev, es4_ev, T, variant):
    es6_ev, es4_ev = np.sort(np.asarray(es6_ev, int)), np.sort(np.asarray(es4_ev, int))
    out = []
    for a in sorted(int(x) for x in starts):
        b = _first_in(es6_ev, a + END_MIN, a + END_MAX)
        if b is None and variant == "P1b":
            b = _first_in(es4_ev, a + END_MIN, a + END_MAX)
        if b is None and variant == "P1c":
            b = a + P1C_LEN
        if b is not None:
            out.append((a, min(b, T)))
    return out


def mask_of(intervals, T):
    m = np.zeros(T, bool)
