def fmt(x, nd=2, sign=False):
    if x is None or (isinstance(x, float) and not np.isfinite(x)):
        return "n/a"
    return ("%+.*f" if sign else "%.*f") % (nd, x)


def pct(x, q):
    return float(np.percentile(x, q)) if len(x) else float("nan")


def load_halves():
    """Per half: the public arrays, the truth side and the type of every long stoppage (typed halves)."""
    import harness
    import dead_census as dc
    M = harness.matches()
    al = dc.aligned_halves()
    out = []
    for mid in sorted(M):
        truth = harness.labels(mid, 2.0)
        vis_a = harness._visibility(mid, "A")
        for hi, half in enumerate(M[mid]["halves"]):
            dead = truth[hi] == D
            fl = flags_of(dead)
            a = al.get((mid, hi))
            if a is None:
                tf = None
            else:
                tf = (lambda e, a=a: (lambda t: t if t in TYPES else "other")(dc.type_of(a["al"], a["types"], e)[0]))
            types = {side: [tf(e) if tf else None for _s, e in fl[side + "_stop"]] for side in ("start", "end")}
            ball_a = np.asarray(half["ball"], float).copy()
