import os
import sys
import time
import warnings

import numpy as np

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
import harness  # noqa: E402
import learned_evidence as le  # noqa: E402
import transition_flip as tf  # noqa: E402

H, A, D, FPS = harness.H, harness.A, harness.D, harness.FPS
WINDOWS = (25, 50, 75)
COLS = tuple("FLIP_%d" % w for w in WINDOWS)
SETTINGS = (("OFF",), ("FLIP",))
OUT_RUN = os.path.join(HERE, "claude_reports", "0109_run.txt")


def flip_columns(home, away):
    """(T, 3) float32: FLIP towards H at windows 25, 50, 75 frames (NaN on a half with an undecided direction)."""
    import restart_shape_public as rs
    import shape_signals as ss
    home, away = np.asarray(home, float), np.asarray(away, float)
    n = len(home)
    dr = rs.direction(home, away)
    if dr is None:
        return np.full((n, len(WINDOWS)), np.nan, np.float32)
    aH = tf.forward_runs(home, dr[0], ss.goalkeeper(home, dr[0]))
    aA = tf.forward_runs(away, dr[1], ss.goalkeeper(away, dr[1]))
    return np.column_stack([tf.flip(aH, aA, w) for w in WINDOWS]).astype(np.float32)


class FlipModels:
    """Nested 84-column models (v1.4-dev's 81 + the flip columns), cached by the excluded set."""

    def __init__(self, ctx, cols):
        self.ctx, self.cols, self.cache = ctx, cols, {}
        self.tabA = {k: np.column_stack([t, cols[k]]) for k, t in ctx["tabs"]["A"].items()}

    def model(self, excluded):
        import night2_panel as n2
        key = frozenset(excluded)
        if key not in self.cache:
            self.cache[key] = n2.fit_rows(self.tabA, self.ctx["frames"], [m for m in self.ctx["ids"]
                                                                          if m not in excluded])
        return self.cache[key]

    def lo(self, rg, x, hi, excluded):
        import night2_panel as n2
        X = np.column_stack([self.ctx["tabs"][rg][(x, hi)], self.cols[(x, hi)]])
        return n2.lo_of(self.model(excluded), X)


def study():
    import explore_short_possessions_2 as ex2
    import night2_panel as n2
    lines = []

    def out(s=""):
        print(s, flush=True)
        lines.append(s)
    t0 = time.time()
    out("REPORT 0109 flip_evidence: v1.4-dev + 3 transition-flip columns (public DFL, 7 matches)")
    with warnings.catch_warnings():
        warnings.simplefilter("ignore")
        ctx = n2.load_context(("R", "A", "S", "D", "C2"), out)
        if ctx is None:
            out("STOP: C does not reproduce")
            return _finish(lines, 1)
        occ = n2.events(ctx)
        cols = {(m, hi): flip_columns(h["home"], h["away"]) for m in ctx["ids"]
                for hi, h in enumerate(harness.matches()[m]["halves"])}
        fm = FlipModels(ctx, cols)
    ids = ctx["ids"]
    out("[context and columns at %d s]" % (time.time() - t0))

    def decode(setting, rg, x, exc):
        if setting == ("OFF",):
            return n2.decode14(ctx, rg, x, exc)
        labs = []
        for hi, fs in enumerate(ctx["fss"][rg][x]):
            lab = le.decode_learned(fs, fm.lo(rg, x, hi, exc), n2.W14)
            lab[np.asarray(fs["dead"], bool)] = D
            labs.append(lab)
        return labs
    with warnings.catch_warnings():
        warnings.simplefilter("ignore")
        diff = sum(a.tobytes() != b.tobytes() for rg in ("R", "A", "S", "D", "C2") for x in ids
                   for a, b in zip(decode(("OFF",), rg, x, {x}), n2.decode14(ctx, rg, x)))
        r1 = n2.mean_of(ctx["truths"][1.0], {x: decode(("OFF",), "R", x, {x}) for x in ids})
    ok = diff == 0 and "%.4f" % r1 == "0.5002"
    out("PROOF: OFF = v1.4-dev on %d of 70 halves differing; R 1 s %.4f: %s" % (diff, r1, "PASS" if ok else "FAIL"))
    if not ok:
        out("STOP")
        return _finish(lines, 1)
    out("")
    with warnings.catch_warnings():
        warnings.simplefilter("ignore")
        res = n2.grid_study(ctx, "FLIP", SETTINGS, ("OFF",), decode, lambda s: SETTINGS.index(s), lambda a, b: a == b,
                            lambda s: s[0], out)
    out("[grid at %d s]" % (time.time() - t0))
    # ------------------------------------------------------------------------------------------------ F5
    out("")
    fixed = {x: decode(("FLIP",), "R", x, {x}) for x in ids}
    for name, p in (("OFF", res["base"]["R"]), ("LOMO", res["lomo_pred"]["R"]), ("FLIP fixed", fixed)):
        for mg in (1.0, 2.0):
            out(n2.anatomy_lines(ctx, p, "R", mg, name)[0])
    for name, p in (("OFF", res["base"]["R"]), ("LOMO", res["lomo_pred"]["R"])):
        leads, never, n = [], 0, 0
        for m in ids:
            for hi in range(2):
                o = occ[(m, hi)]
                raw = ctx["raw"][m][hi]
                live = ~np.asarray(ctx["C"][(m, hi)], bool)
                for s, k, direct in ex2.true_changes(raw):
                    if not direct or not live[s]:
                        continue
                    d = np.abs(o["frames"] - s)
                    if not len(d) or d.min() > 25 or o["sits"][int(np.argmin(d))] != "PASS INTERCEPTED":
                        continue
                    n += 1
                    f = tf.first_label(p[m][hi], max(0, s - 50), min(len(raw), s + 101), k)
                    if f is None:
                        never += 1
                    else:
                        leads.append((f - s) / FPS)
        q = np.percentile(leads, [25, 50, 75]) if leads else [np.nan] * 3
        out("TIMING %s at PASS INTERCEPTED changes (R): %d changes; first label of the new team minus the change: median "
            "%+.2f s [%+.2f, %+.2f]; never labelled in [s - 2 s, s + 4 s] %d (%.3f)"
            % (name, n, q[1], q[0], q[2], never, never / max(1, n)))
    # permutation importance of the three columns (regime A, held out)
    imp = np.zeros(3)
    for i, x in enumerate(ids):
        mdl = fm.model({x})
        X, y = [], []
        for hi in range(2):
            mask, truth = ctx["frames"][(x, hi)]
            idx = np.flatnonzero(mask)[::le.SUB]
            X.append(np.column_stack([ctx["tabs"]["A"][(x, hi)], cols[(x, hi)]])[idx])
            y.append(truth[idx] == H)
        X, y = np.vstack(X), np.concatenate(y)

        def ll(Xm):
            p = 1 / (1 + np.exp(-np.asarray(mdl.decision_function(Xm), float)))
            p = np.clip(p, 1e-9, 1 - 1e-9)
            return float(-np.mean(y * np.log(p) + (1 - y) * np.log(1 - p)))
        base = ll(X)
        for j in range(3):
            Xp = X.copy()
            Xp[:, 81 + j] = np.random.default_rng(1000 * i + j).permutation(Xp[:, 81 + j])
            imp[j] += (ll(Xp) - base) / len(ids)
    out("IMPORTANCE (held-out log-loss increase, regime A, mean over 7): %s" % ", ".join("%s %+.4f" % (c, v)
                                                                                        for c, v in zip(COLS, imp)))
    out("[done in %d s]" % (time.time() - t0))
    return _finish(lines, 0)


def _finish(lines, code):
    with open(OUT_RUN, "w") as f:
        f.write("\n".join(lines) + "\n")
    return code


def main(argv=None):
    argv = sys.argv[1:] if argv is None else argv
    if argv:
        sys.exit("flip_evidence.py takes no arguments")
    return study()


if __name__ == "__main__":
    sys.exit(main())
