import explore_short_possessions_2 as ex2  # noqa: E402  (true_changes, start_classes, count_within)
import football_error_audit as fa  # noqa: E402  (report 0096: events, alignment, situations, errors, window)
import l1a_measure as l1a  # noqa: E402  (boundaries)

FPS = 25
H, A, D = 0, 1, 2
