OUT_RUN = os.path.join(HERE, "claude_reports", "0097_run.txt")
OUT_CAUSES = os.path.join(HERE, "claude_reports", "0097_causes.txt")

CAUSES = ("C1", "C2", "C3", "C4", "C5", "C6")
SUBS = ("C1a", "C1b", "C1c", "C1d", "C1e")
NAMES = {"C1": "DEAD-BALL EDGE", "C2": "DELIVERY INTO THE BOX", "C3": "WIN SEEN LATE",
         "C4": "POSSESSION AFTER A WIN MISSED", "C5": "SHORT BLIP OR SCRAMBLE", "C6": "NO EVENT",
         "C1a": "live play called dead after a restart", "C1b": "goalkeeper holding the ball",
         "C1c": "ball out called late or missed", "C1d": "restart given to the wrong team",
         "C1e": "other dead-ball edge", "NONE": "none of C1-C6", "ALL": "all errors"}
RESTARTS = ("THROW-IN", "CORNER", "FREE KICK", "GOAL KICK", "KICK-OFF")
DELIVERY = ("CROSS", "CORNER", "FREE KICK", "LONG BALL / CLEARANCE", "GOAL KICK", "THROW-IN")
WINS = ("BALL CLAIMED / INTERCEPTION", "PASS INTERCEPTED", "GROUND DUEL / TACKLE WON", "AERIAL DUEL")
EDGE_F, RUN_F, RESTART_F, LATE_F, DELIV_F, WIN_F = 50, 50, 250, 25, 100, 25     # F1 to F3 (2 s, 2 s, 10 s, 1 s, 4 s, 1 s)
C3_LO, C3_HI, C4_LO, C4_HI, SHORT_F = 25, 100, 50, 150, 50                      # F3 to F5
TEAM_AT, RIGHT_AT, VANISH_F = 12, 25, 25                                        # F2, F10
BOX_X0, BOX_X1, BOX_Y = 36.0, 52.5, 20.16
LATE_BINS = ((25, 50, "1-2 s"), (50, 75, "2-3 s"), (75, 101, "3-4 s"))
SNAPS = (-1, 0, 1, 2, 3)
