SHORT_KIND = {"MISSED": "MISSED", "FALSE": "FALSE", "LATE END": "LATE", "WRONG TEAM": "WRONG"}
MERGES, ERR_MERGE, REGIMES = (0.0, 0.5, 1.0, 2.0), 1.0, ("A", "S")
