PROOF_ERR = {"A": (2202, {"MISSED": 1046, "FALSE": 267, "LATE END": 532, "WRONG TEAM": 357}), "S": (2526, None)}


# ------------------------------------------------------------------------------------------------ pieces
def runs(mask, min_len=1):
    """[(s, e)] maximal True runs of at least min_len frames."""
    m = np.asarray(mask, bool)
    e = np.flatnonzero(np.diff(np.r_[0, m.astype(np.int8), 0]))
    return [(int(a), int(b)) for a, b in zip(e[::2], e[1::2]) if b - a >= min_len]


def edges(stretches, n):
    """F1: start edges (first frame) and end edges (first frame after) of D stretches; frame 0 and n are no edges."""
    out = [s for s, _e in stretches if s > 0] + [e for _s, e in stretches if e < n]
    return np.array(sorted(out), int)


def near(a, frames, tol):
    frames = np.asarray(frames)
    return bool(len(frames) and np.any(np.abs(frames - a) <= tol))


def inside(a, rs):
    return any(s <= a < e for s, e in rs)


def in_box(x, y):
    return bool(BOX_X0 <= abs(x) <= BOX_X1 and abs(y) <= BOX_Y)


def window_mask(anchors, n):
    """F8: the union of [a - 25, a + 75) over the anchors, clipped (report 0096's prize window)."""
    m = np.zeros(n, bool)
    for a in anchors:
        m[max(0, a - fa.WIN_BEFORE):min(n, a + fa.WIN_AFTER)] = True
    return m


def replace_on_windows(pred, truth, anchors):
    return fa.with_truth(pred, truth, anchors)


def deliveries(frames, sits, events, teams, ball):
    """F2: (deliveries into the box, every delivery whose next event is a contact within 4 s with a box decision).
    Each: dict(j, fd, fc, type, side (delivering team), contact_side, box, ev_box, src)."""
    n = len(ball)
    cands = []
    for j, s in enumerate(sits):
        if s not in DELIVERY or j + 1 >= len(sits):
            continue
        fd, fcn, nx = int(frames[j]), int(frames[j + 1]), events[j + 1]
        if not fa.is_contact(nx) or not 0 <= fcn - fd <= DELIV_F:
            continue
        evb = None if nx["x"] is None or nx["y"] is None else in_box(nx["x"] - fa.L_HALF, nx["y"] - fa.W_HALF)
        b = np.asarray(ball[min(fcn, n - 1)], float)
        if np.all(np.isfinite(b)):
            box, src = in_box(b[0], b[1]), "ball"
        elif evb is not None:
            box, src = evb, "event"
        else:
            continue
        cands.append(dict(j=j, fd=fd, fc=fcn, type=s, side=teams[j], contact_side=teams[j + 1], box=box, ev_box=evb,
                          src=src))
    return [d for d in cands if d["box"]], cands


def contact_team(d, truth0, n):
    """F2: who truly has the ball 0.48 s after the first contact: delivering, defending, D (or unknown team)."""
    t = int(truth0[min(d["fc"] + TEAM_AT, n - 1)])
    if t == D:
        return "D"
    if d["side"] is None:
        return "unknown"
    return "delivering" if LETTER[t] == d["side"] else "defending"


def right_after(d, pred, truth, n):
    """F2: v1.4-dev equals the truth 1 s after the first contact (None when that truth is D)."""
    g = min(d["fc"] + RIGHT_AT, n - 1)
    if truth[g] > A:
        return None
    return bool(pred[g] == truth[g])


def changes(truth, pred, frames, sits):
    """F3: every true direct change with its win event (within 1 s, nearest, ties earlier), the nearest predicted
    switch of the same direction (ties earlier, no limit), its lateness, and whether it is a C3 change."""
    pbs = l1a.boundaries(np.asarray(pred))
    wi = [i for i, s in enumerate(sits) if s in WINS]
    wf = np.array([frames[i] for i in wi], int)
    out = []
    for s, k, direct in ex2.true_changes(truth):
        if not direct:
            continue
        j = int(truth[s - 1])
        win, wfr = None, None
        if len(wf):
            dd = np.abs(wf - s)
            i = int(np.argmin(dd))
            if dd[i] <= WIN_F:
                win, wfr = sits[wi[i]], int(wf[i])
        cand = [p for p, pf, pt in pbs if pf == j and pt == k]
        p = min(cand, key=lambda x: (abs(x - s), x)) if cand else None
        late = None if p is None else int(p - s)
        out.append(dict(s=int(s), j=j, k=int(k), win=win, wf=wfr, p=p, late=late,
                        c3=win is not None and late is not None and C3_LO <= late <= C3_HI,
                        ontime=win is not None and late is not None and abs(late) < LATE_F))
    return out


def c4_possessions(truth, pred):
    """F4: [(s, e, k)] true possessions of 2 to 6 s at a direct change, MISSED, with no frame of team k predicted."""
    pred = np.asarray(pred)
    direct = {s for s, _k, d in ex2.true_changes(truth) if d}
    return [(s, e, k) for s, e, k, cls, _p, _pe in ex2.start_classes(truth, pred)
            if s in direct and C4_LO <= e - s <= C4_HI and cls == "MISSED" and not np.any(pred[s:e] == k)]


def half_context(truth, truth0, pred, frames, sits, events, teams, ball):
    """Everything the cause rules need for one half: truth at merge 1 s, the raw truth (merge 0), the prediction,
    the events (report 0096's occurrences in its order: frames, situations, event dicts, acting teams H / A / None)
    and the public ball."""
    truth, truth0, pred = np.asarray(truth), np.asarray(truth0), np.asarray(pred)
    frames = np.asarray(frames, int)
    n = len(truth)
    c = SimpleNamespace(n=n, truth=truth, pred=pred, frames=frames, sits=list(sits))
    c.live_t, c.live_p = truth <= A, pred <= A
    c.t_str, c.p_str = runs(truth == D), runs(pred == D)
    c.t_edges, c.p_edges = edges(c.t_str, n), edges(c.p_str, n)
    c.p_starts = np.array([s for s, _e in c.p_str], int)
    c.lcd = c.live_t & (pred == D)
    c.lcd_runs, c.dcl_runs = runs(c.lcd, RUN_F), runs((truth == D) & c.live_p, RUN_F)
    pick = lambda names: np.array([f for f, s in zip(frames, sits) if s in names], int)  # noqa: E731
    c.restart, c.gk, c.scramble = pick(RESTARTS), pick(("GOALKEEPER ACTION",)), pick(("LOOSE BALL / SCRAMBLE",))
    c.deliveries, c.delivery_cands = deliveries(frames, c.sits, events, teams, ball)
    c.changes = changes(truth, pred, frames, c.sits)
    c.c4 = c4_possessions(truth, pred)
    c.short = [(s, e) for s, e, _k in esp.spells_of(truth0) if e - s < SHORT_F]
    return c


def _c1c(s, e, c):
    if c.pred[s] == D:
        return False
    later = c.p_starts[(c.p_starts > s) & (c.p_starts < e)]
    return not len(later) or int(later[0]) - s > LATE_F


def _c1d(g, c):
    idx = np.flatnonzero(c.live_p[g:])
    if not len(idx):
        return False
    f = g + int(idx[0])
    return bool(c.live_t[g:f + 1].all() and c.pred[f] != c.truth[f])


def first_match(r):
    return next((x for x in CAUSES if r[x]), "NONE")


def classify(kind, a, c):
    """F1 to F7 for one error (kind, anchor a) of one half's context c: {C1..C6: bool, subs: {C1a..C1e: bool},
    first, sub_first}. The rules do not depend on the kind; it is passed for the record."""
    r = {"kind": kind}
    r["C1"] = (near(a, c.t_edges, EDGE_F) or near(a, c.p_edges, EDGE_F) or inside(a, c.lcd_runs)
               or inside(a, c.dcl_runs))
    subs = dict.fromkeys(SUBS, False)
    if r["C1"]:
        subs["C1a"] = bool(np.any((c.restart >= a - RESTART_F) & (c.restart <= a))
                           and c.lcd[max(0, a - EDGE_F):a + EDGE_F + 1].any())
        subs["C1b"] = near(a, c.gk, EDGE_F)
        subs["C1c"] = any(_c1c(s, e, c) for s, e in c.t_str if s > 0 and abs(s - a) <= EDGE_F)
        subs["C1d"] = any(_c1d(e, c) for _s, e in c.t_str if e < c.n and abs(e - a) <= EDGE_F)
        subs["C1e"] = not any(subs[x] for x in SUBS[:4])
    r["subs"] = subs
    r["sub_first"] = next((x for x in SUBS if subs[x]), None)
    r["C2"] = any(0 <= a - d["fd"] <= DELIV_F for d in c.deliveries)
    r["C3"] = any(ch["c3"] and ch["s"] <= a <= ch["p"] for ch in c.changes)
    r["C4"] = any(s <= a <= e for s, e, _k in c.c4)
    r["C5"] = any(s <= a <= e for s, e in c.short) or near(a, c.scramble, EDGE_F)
    r["C6"] = not near(a, c.frames, EDGE_F)
    r["first"] = first_match(r)
    return r


def overlap(masks):
    """F9: {X: {Y: |W_X and W_Y| / |W_X|}}; masks = {X: [boolean array per half]} (same halves, same order)."""
    out = {}
    for x, mx in masks.items():
        nx = sum(int(m.sum()) for m in mx)
        out[x] = {y: (sum(int((a & b).sum()) for a, b in zip(mx, my)) / nx if nx else float("nan"))
                  for y, my in masks.items()}
    return out


def exact_edges(C, truth):
    """F10: C* = C stretches overlapping no truth D stretch, united with truth D stretches overlapping a C stretch."""
    C, td = np.asarray(C, bool), np.asarray(truth) == D
    out = np.zeros(len(C), bool)
    for s, e in runs(C):
        if not td[s:e].any():
            out[s:e] = True
    for s, e in runs(td):
        if C[s:e].any():
            out[s:e] = True
    return out


def vanished(old, new):
    """F10: per old error (kind, anchor): True if new holds no error of the same kind within 25 frames."""
    by = defaultdict(list)
    for k, a in new:
        by[k].append(a)
    by = {k: np.array(sorted(v)) for k, v in by.items()}
    return [not near(a, by.get(k, ()), VANISH_F) for k, a in old]


def dead_counts(truth, pred, mask):
    """F10: TP, FP, FN, TN of the prediction's D against the truth's D on the mask's frames."""
    td, pd = (np.asarray(truth) == D)[mask], (np.asarray(pred) == D)[mask]
    return dict(TP=int((td & pd).sum()), FP=int((~td & pd).sum()), FN=int((td & ~pd).sum()), TN=int((~td & ~pd).sum()))


def f1(c):
    d = 2 * c["TP"] + c["FP"] + c["FN"]
    return 2 * c["TP"] / d if d else float("nan")


def nearest_dist(xy, ball):
    import warnings
    d = np.hypot(xy[:, :, 0] - ball[:, None, 0], xy[:, :, 1] - ball[:, None, 1])
    with warnings.catch_warnings():
        warnings.simplefilter("ignore")
        return np.nanmin(np.where(np.isfinite(d), d, np.nan), axis=1)


# ------------------------------------------------------------------------------------------------ the study
def load(out):
    """Report 0096's setting, step for step as football_error_audit.study() builds it (that function is not changed;
    its loading lines are repeated here): C, the matches, the LA tables, the truths, the nested v1.4-dev predictions
    and log-odds, the events with E0's offset and E1's situations."""
    import time
    import warnings
    import harness
    import learned_evidence as le
    import lookahead_evidence as la
    import overnight_grid as og
    import pressure_cues as pc
    import realistic_ball_regime as rb
    import restart_shape_public as rs
    import shape_signals as ss
    t0 = time.time()
    C = og.load_C(lambda s: out("[" + s + "]" if "[" in s else s))
    if C is None:
        return None
    folder = fa.data_dir()
    with warnings.catch_warnings():
        warnings.simplefilter("ignore")
        M = harness.matches()
        ids = sorted(M)
        players = ss.all_features(os.environ.get("MTAH_SHAPE_CACHE"))
        for m in ids:
            for hi, h in enumerate(M[m]["halves"]):
                players[(m, hi)] = dict(players[(m, hi)], **pc.press_features(h["home"], h["away"]))
        shapes = ex2.team_shapes(os.environ.get("MTAH_TEAMSHAPE_CACHE"))
        fss = {"A": {m: harness.features(m, 2.0, "A", ("mask", C)) for m in ids},
               "S": {m: rb.s_features(m, C) for m in ids}}
        balls = {"A": {}, "S": {}}
        for m in ids:
            for hi, (fs, h) in enumerate(zip(fss["S"][m], M[m]["halves"])):
                balls["S"][(m, hi)] = rb.smooth_runs(h["ball"], np.asarray(fs["ball_visible"], bool))
                balls["A"][(m, hi)] = np.asarray(h["ball"], float)
        tabs = {rg: {(m, hi): la.la_table(fs, players[(m, hi)], balls[rg][(m, hi)], shapes[(m, hi)])
                     for m in ids for hi, fs in enumerate(fss[rg][m])} for rg in REGIMES}
        truths = {mg: {m: harness.labels(m, mg) for m in ids} for mg in MERGES}
        frames = {(m, hi): (~np.asarray(C[(m, hi)], bool) & (t <= harness.A), t)
                  for m in ids for hi, t in enumerate(truths[2.0][m])}
        out("[tables at %d s]" % (time.time() - t0))
        pred, lo = {rg: {} for rg in REGIMES}, {rg: {} for rg in REGIMES}
        for x in ids:
            model = la.fit_variant({"A": tabs["A"]}, frames, [y for y in ids if y != x], "TA")
            for rg in REGIMES:
                pred[rg][x] = []
                for hi, fs in enumerate(fss[rg][x]):
                    v = np.asarray(model.decision_function(tabs[rg][(x, hi)]), float)
                    lab = le.decode_learned(fs, v, la.W_GRID[1])
                    lab[fs["dead"]] = harness.D
                    lo[rg][(x, hi)] = v
                    pred[rg][x].append(lab)
        out("[nested models and decoding at %d s]" % (time.time() - t0))
        occ = {}
        for m in ids:
            halves = M[m]["halves"]
            n_frames = [len(h["lab"]) for h in halves]
            evs = [e for e in fa.parse_events(fa.file_of("events", m, folder)) if e["path"] != "Delete"]
            secs = fa.ball_frames(fa.file_of("positions", m, folder))
            links, tids = fa.teamsheet_links(m, folder)
            side_of = {tids["Home"]: "H", tids["Away"]: "A"}
            fr, _info = fa.align(evs, secs, n_frames, halves, links)
            for hi, h in enumerate(halves):
                idx = sorted((i for i, (hh, _f) in enumerate(fr) if hh == hi), key=lambda i: (fr[i][1], evs[i]["t"], i))
                es = [evs[i] for i in idx]
                ff = [fr[i][1] for i in idx]
                gk = [bool(e["player"] in links and links[e["player"]][2] == "TW") for e in es]
                sits = fa.map_half(es, ff, gk)
                keep = [j for j, sname in enumerate(sits) if sname is not None]
                occ[(m, hi)] = dict(frames=np.array([ff[j] for j in keep], int), sits=[sits[j] for j in keep],
                                    events=[es[j] for j in keep],
                                    teams=[side_of.get(fa.acting_team(es[j])) for j in keep])
        out("[events at %d s]" % (time.time() - t0))
    return dict(C=C, M=M, ids=ids, fss=fss, truths=truths, pred=pred, lo=lo, occ=occ, decode=le.decode_learned,
                w=la.W_GRID[1], harness=harness)


def fmt_ci(r):
    return "%+.4f [%+.4f, %+.4f]" % (r["diff"], r["lo"], r["hi"])


def study():
    import time
    import warnings
    lines = []

    def out(s=""):
        print(s, flush=True)
        lines.append(s)

    def finish(code):
        with open(OUT_RUN, "w") as f:
            f.write("\n".join(lines) + "\n")
        print("wrote %s" % os.path.relpath(OUT_RUN, HERE))
        return code
    t0 = time.time()
    out("REPORT 0097: FOOTBALL CAUSES over ALL of v1.4-dev's errors (EXPLORE; descriptive only, no fix, no decoder "
        "change, no verdict, no recommendation); report 0096's setting; rules F0 to F11")
    S = load(out)
    if S is None:
        out("STOP: C does not reproduce")
        return finish(1)
    hn, ids, truths, pred, lo, occ, M, C, fss = (S["harness"], S["ids"], S["truths"], S["pred"], S["lo"], S["occ"],
                                                  S["M"], S["C"], S["fss"])
    halves = [(m, hi) for m in ids for hi in range(len(M[m]["halves"]))]
    # ---------------------------------------------------------------------------------------- F0 proof
    a2 = float(np.mean([hn._score_match(truths[2.0][m], pred["A"][m]) for m in ids]))
    ok = round(a2, 4) == PROOF_A2
    out("PROOF v1.4-dev regime A merge 2 s: 7-match mean spellF1 %.4f (report 0096: %.4f): %s"
        % (a2, PROOF_A2, "PASS" if ok else "FAIL"))
    errs = {rg: [] for rg in REGIMES}
    for rg in REGIMES:
        for m, hi in halves:
            for kind, a, _det in fa.errors_half(truths[ERR_MERGE][m][hi], pred[rg][m][hi]):
                errs[rg].append((m, hi, kind, int(a)))
        tot = Counter(e[2] for e in errs[rg])
        want_n, want_k = PROOF_ERR[rg]
        good = len(errs[rg]) == want_n and (want_k is None or all(tot[k] == want_k[k] for k in KINDS))
        out("PROOF errors regime %s merge 1 s: %d (%s); report 0096: %d: %s"
            % (rg, len(errs[rg]), ", ".join("%s %d" % (k, tot[k]) for k in KINDS), want_n, "PASS" if good else "FAIL"))
        ok = ok and good
    same_d = all(np.array_equal(np.asarray(pred[rg][m][hi]) == D, np.asarray(C[(m, hi)], bool))
                 for rg in REGIMES for m, hi in halves)
    out("CHECK predicted D equals mask C on all %d halves, both regimes: %s" % (len(halves), "PASS" if same_d else "FAIL"))
    if not ok or not same_d:
        out("STOP: proof fails")
        return finish(1)
    out("PROOF: PASS")

    # ---------------------------------------------------------------------------------------- F1-F7 classify
    with warnings.catch_warnings():
        warnings.simplefilter("ignore")
        ctx = {(rg, m, hi): half_context(truths[ERR_MERGE][m][hi], truths[0.0][m][hi], pred[rg][m][hi],
                                         occ[(m, hi)]["frames"], occ[(m, hi)]["sits"], occ[(m, hi)]["events"],
                                         occ[(m, hi)]["teams"], np.asarray(M[m]["halves"][hi]["ball"], float))
               for rg in REGIMES for m, hi in halves}
    cls = {rg: [classify(k, a, ctx[(rg, m, hi)]) for m, hi, k, a in errs[rg]] for rg in REGIMES}
    rows_txt = ["regime,match,half,kind,anchor_frame,first,all_match,c1_first,c1_all_match"]
    for rg in REGIMES:
        for (m, hi, k, a), r in zip(errs[rg], cls[rg]):
            rows_txt.append("%s,%s,%d,%s,%d,%s,%s,%s,%s" % (rg, m, hi + 1, k, a, r["first"],
                                                           "+".join(x for x in CAUSES if r[x]) or "-",
                                                           r["sub_first"] or "-",
                                                           "+".join(x for x in SUBS if r["subs"][x]) or "-"))
    with open(OUT_CAUSES, "w") as f:
        f.write("\n".join(rows_txt) + "\n")
    out("[causes at %d s]" % (time.time() - t0))

    def members(rg, row, mode):
        """Indices of the errors of a row: cause or sub-cause, all-match or first-match; NONE; ALL."""
        rs_ = cls[rg]
        if row == "ALL":
            return list(range(len(rs_)))
        if row == "NONE":
            return [i for i, r in enumerate(rs_) if r["first"] == "NONE"]
        if row in CAUSES:
            return [i for i, r in enumerate(rs_) if (r[row] if mode == "all" else r["first"] == row)]
        return [i for i, r in enumerate(rs_) if (r["subs"][row] if mode == "all" else
                                                 (r["first"] == "C1" and r["sub_first"] == row))]

    def anchors_of(rg, idx):
        by = defaultdict(list)
        for i in idx:
            m, hi, _k, a = errs[rg][i]
