            rows_["nearest %s (m)" % roles[1]].append("%.2f" % med(d2))
            rows_["crowd 5 m %s" % roles[0]].append("%.1f" % med(c1))
            rows_["crowd 5 m %s" % roles[1]].append("%.1f" % med(c2))
