import datetime as dt
import os
import sys
import xml.etree.ElementTree as ET
from collections import Counter, defaultdict

import numpy as np

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)

FPS = 25
OUT_INV = os.path.join(HERE, "claude_reports", "0096_inventory.txt")
OUT_RUN = os.path.join(HERE, "claude_reports", "0096_run.txt")
OUT_ERR = os.path.join(HERE, "claude_reports", "0096_errors.txt")
