EDGE = 50                                      # events up to 2 s outside a half's tracking are clipped into it
OFFSETS = tuple(range(-50, 51))                # the alignment check's frame offsets
TRANSFORMS = {"x-52.5, y-34": (1, 1), "x-52.5, 34-y": (1, -1), "52.5-x, y-34": (-1, 1), "52.5-x, 34-y": (-1, -1)}
L_HALF, W_HALF = 52.5, 34.0


# ------------------------------------------------------------------------------------------------ files and times
def data_dir():
    from floodlight.io.datasets import IDSSEDataset
    return IDSSEDataset(match_id="J03WMX")._data_dir


def file_of(kind, mid, folder=None):
    """The public DFL file of a match: kind 'events', 'positions' or 'info'."""
    folder = folder or data_dir()
    comp = "DFL-COM-000001" if mid in ("J03WMX", "J03WN1") else "DFL-COM-000002"
    stem = {"events": "DFL_03_02_events_raw", "positions": "DFL_04_03_positions_raw_observed",
            "info": "DFL_02_01_matchinformation"}[kind]
    return os.path.join(folder, "%s_%s_DFL-MAT-%s.xml" % (stem, comp, mid))


def iso_seconds(text):
    """Epoch seconds of an ISO 8601 time with its offset ('2023-05-27T15:30:12.230+02:00')."""
    return dt.datetime.fromisoformat(text).timestamp()


def ball_frames(pos_path):
    """[(game section, first N, epoch seconds of the first frame, last N)] of the ball's frame sets, in file order
    (floodlight's arrays start at the first ball frame of each section)."""
    out, cur, prev = [], None, None
    with open(pos_path, "rb") as f:
        it = iter(f)
        for line in it:
            if cur is None:
                if b'TeamId="BALL"' in line or b"TeamId=\"Ball\"" in line:
                    sec = line.split(b'GameSection="')[1].split(b'"')[0].decode()
                    first = next(it)
                    n0 = int(first.split(b' N="')[1].split(b'"')[0])
                    t0 = iso_seconds(first.split(b' T="')[1].split(b'"')[0].decode())
                    cur, prev = (sec, n0, t0), first
            elif line.lstrip().startswith(b"</FrameSet>"):
                out.append(cur + (int(prev.split(b' N="')[1].split(b'"')[0]),))
                cur = None
            else:
                prev = line
    return out


def parse_events(path):
    """[event dict] in file order: id, t (epoch s), x, y (the file's coordinates or None), path (element chain under
    <Event>, e.g. 'ThrowIn/Play/Pass'), q (every attribute of the chain's elements, deeper ones last), team, player,
    teams (the set of teams the event involves)."""
    out = []
    for ev in ET.parse(path).getroot().iter("Event"):
        kids = list(ev)
        chain, q, node = [], {}, ev
        while kids:
            node = kids[0]
            chain.append(node.tag)
            q.update(node.attrib)
            kids = list(node)
        for extra in ev.iter():                      # attributes of any further elements (none expected)
            if extra is not ev and extra.tag not in chain:
                q.update({"%s.%s" % (extra.tag, k): v for k, v in extra.attrib.items()})
        x, y = ev.get("X-Position"), ev.get("Y-Position")
        team = q.get("Team") or q.get("WinnerTeam")
        teams = {q[k] for k in ("Team", "WinnerTeam", "LoserTeam") if k in q}
        out.append(dict(id=ev.get("EventId"), t=iso_seconds(ev.get("EventTime")), x=None if x is None else float(x),
                        y=None if y is None else float(y), path="/".join(chain), q=q, team=team,
                        player=q.get("Player") or q.get("Winner"), teams=teams))
    return out


def frame_of(t, t0, offset=0):
    return int(round((t - t0) * FPS)) + offset


def assign_halves(events, sections, n_frames, offset=0):
    """Each event's (half, frame): the half whose tracking holds its frame (up to EDGE frames outside, clipped);
    (None, None) otherwise. sections = ball_frames(); n_frames = frames per half in the loaded tracking."""
    out = []
    for e in events:
        got = (None, None)
        for hi, ((_sec, _n0, t0, _n1), n) in enumerate(zip(sections, n_frames)):
            f = frame_of(e["t"], t0, offset)
            if -EDGE <= f < n + EDGE:
                got = (hi, min(max(f, 0), n - 1))
                break
        out.append(got)
    return out


def teamsheet_links(mid, folder=None):
    """{pID: ("Home" | "Away", column index in floodlight's arrays, position, jID)} and {"Home": tID, "Away": tID}."""
    import floodlight.io.dfl as dfl
    ts = dfl.read_teamsheets_from_mat_info_xml(file_of("info", mid, folder))
    links, tids = {}, {}
    for side in ("Home", "Away"):
        t = ts[side]
        if "xID" not in t.teamsheet.columns:
            t.add_xIDs()
        df = t.teamsheet
        tids[side] = str(df["tID"].iloc[0])
        for _i, r in df.iterrows():
            links[str(r["pID"])] = (side, int(r["xID"]), r["position"], int(r["jID"]))
    return links, tids


# ------------------------------------------------------------------------------------------------ step 1: inventory
ID_LIKE = ("Team", "Player", "Recipient", "Winner", "Loser", "WinnerTeam", "LoserTeam", "TeamLeft", "TeamRight",
           "PlayerIn", "PlayerOut", "Fouler", "Fouled", "TeamFouler", "TeamFouled", "Guardian", "DecisionTimestamp",
           "BallPossessionPhase", "PlayAngle", "Minute", "Second")


def categorical(attr, values):
    """True if the attribute's values are counted one by one (False: presence only): not an ID, a time, an angle,
    a phase counter or a number, and at most 12 distinct values."""
    if attr in ID_LIKE or attr.endswith("Team") or any(str(v).startswith("DFL-") for v in values):
        return False
    try:
        [float(v) for v in values]
        return False
    except ValueError:
        pass
    return len(set(values)) <= 12


def inventory_lines(per_match):
    """per_match = {match: [event]} -> the inventory's type and qualifier tables (text lines)."""
    ids = sorted(per_match)
    lines = ["TYPES (element chain under <Event>), counts per match: " + " | ".join(ids) + " | total"]
    types = {m: Counter(e["path"] for e in per_match[m]) for m in ids}
    allt = sorted(set().union(*types.values()), key=lambda p: (-sum(types[m][p] for m in ids), p))
    for p in allt:
        lines.append("TYPE %-40s | %s | %d" % (p, " | ".join("%4d" % types[m][p] for m in ids),
                                                 sum(types[m][p] for m in ids)))
    lines.append("")
    lines.append("QUALIFIERS per type (attribute=value for categorical attributes, attribute=<present> otherwise), "
                 "counts per match: " + " | ".join(ids) + " | total")
    for p in allt:
        vals = defaultdict(list)
        for m in ids:
            for e in per_match[m]:
                if e["path"] == p:
                    for k, v in e["q"].items():
                        vals[k].append(v)
        for k in sorted(vals):
            cat = categorical(k, vals[k])
            keys = sorted(set(vals[k])) if cat else ["<present>"]
            for v in keys:
                c = {m: sum(1 for e in per_match[m] if e["path"] == p and k in e["q"]
                            and (not cat or e["q"][k] == v)) for m in ids}
                lines.append("QUAL %-32s %s=%s | %s | %d" % (p, k, v, " | ".join("%4d" % c[m] for m in ids),
                                                            sum(c.values())))
    return lines


def player_ball_curve(events, frames, halves, links, offsets=OFFSETS):
    """{offset: [distance player-ball]} for events with a player in the teamsheet, both positions known."""
    out = {k: [] for k in offsets}
    for e, (hi, f) in zip(events, frames):
        if hi is None or e["player"] not in links:
            continue
        side, j, _pos, _jid = links[e["player"]]
        h = halves[hi]
        xy = h["home"] if side == "Home" else h["away"]
        if j >= xy.shape[1]:
            continue
        n = len(h["ball"])
        for k in offsets:
            g = f + k
            if 0 <= g < n:
                d = float(np.hypot(*(xy[g, j] - h["ball"][g])))
                if np.isfinite(d):
                    out[k].append(d)
    return out


def coordinate_check(events, frames, halves):
    """{transform: [distance event position - ball]} at the event frame."""
    out = {k: [] for k in TRANSFORMS}
    for e, (hi, f) in zip(events, frames):
        if hi is None or e["x"] is None:
            continue
        b = halves[hi]["ball"][f]
        if not np.all(np.isfinite(b)):
            continue
        for k, (sx, sy) in TRANSFORMS.items():
            out[k].append(float(np.hypot(sx * (e["x"] - L_HALF) - b[0], sy * (e["y"] - W_HALF) - b[1])))
    return out


def best_offset(curve):
    """(offset with the smallest median distance (ties: the smaller |offset|, then the smaller), that median)."""
    med = {k: float(np.median(v)) for k, v in curve.items() if v}
    k = min(med, key=lambda x: (med[x], abs(x), x))
    return k, med[k]


def load_match_events(mid, n_frames, folder=None, offset=0):
    """(events without Delete placeholders, [(half, frame)], number of Delete placeholders, sections)."""
    evs = parse_events(file_of("events", mid, folder))
    n_del = sum(e["path"] == "Delete" for e in evs)
    evs = [e for e in evs if e["path"] != "Delete"]
    secs = ball_frames(file_of("positions", mid, folder))
    return evs, assign_halves(evs, secs, n_frames, offset), n_del, secs


def inventory():
    import time
    import warnings
    import harness
    lines = []

    def out(s=""):
        print(s, flush=True)
        lines.append(s)
    t0 = time.time()
    out("REPORT 0096 STEP 1: EVENT INVENTORY of the 7 public DFL matches (raw event XML) and the frame matching; no "
        "error is computed in this step")
    folder = data_dir()
    with warnings.catch_warnings():
        warnings.simplefilter("ignore")
        M = harness.matches()
    ids = sorted(M)
    per_match, frames_of, links_of = {}, {}, {}
    curves_all = {k: [] for k in OFFSETS}
    coord_all = {k: [] for k in TRANSFORMS}
    for m in ids:
        halves = M[m]["halves"]
        n_frames = [len(h["lab"]) for h in halves]
        evs, fr, n_del, secs = load_match_events(m, n_frames, folder)
        links, tids = teamsheet_links(m, folder)
        per_match[m], frames_of[m], links_of[m] = evs, fr, links
        lens = [s[3] - s[1] + 1 for s in secs]
        n_out = sum(h is None for h, _f in fr)
        n_edge = sum(1 for e, (h, f) in zip(evs, fr) if h is not None and
                     not (0 <= frame_of(e["t"], secs[h][2]) < n_frames[h]))
        out("MATCH %s: events %d (plus %d Delete placeholders, dropped); in half 1 %d, half 2 %d, outside both halves "
            "%d; clipped from up to 2 s outside a half %d | ball frame sets %s, frames %s, tracking halves %s (%s)"
            % (m, len(evs), n_del, sum(h == 0 for h, _f in fr), sum(h == 1 for h, _f in fr), n_out, n_edge,
               ", ".join(s[0] for s in secs), lens, n_frames, "equal" if lens == n_frames else "DIFFERENT"))
        cur = player_ball_curve(evs, fr, halves, links)
        k, med = best_offset(cur)
        out("ALIGN %s: player-ball distance at the event frame (offset 0): median %.2f m (n %d, within 2 m %.0f%%); "
            "best offset %+d frames (median %.2f m)" % (m, float(np.median(cur[0])), len(cur[0]),
                                                       100 * np.mean(np.asarray(cur[0]) <= 2), k, med))
        for kk in OFFSETS:
            curves_all[kk] += cur[kk]
        cc = coordinate_check(evs, fr, halves)
        for kk in TRANSFORMS:
            coord_all[kk] += cc[kk]
    k, med = best_offset(curves_all)
    out("")
    out("ALIGN ALL: the event frame = round((EventTime - time of the half's first ball frame) x 25); player-ball "
        "median distance by offset (frames): " + ", ".join("%+d: %.2f" % (kk, float(np.median(curves_all[kk])))
                                                           for kk in (-50, -25, -12, -8, -4, -2, -1, 0, 1, 2, 4, 8,
                                                                      12, 25, 50)))
    out("ALIGN ALL: best offset %+d frames (median %.2f m; at 0: %.2f m); share within 2 m at the best offset %.0f%%, "
        "at 0 %.0f%%" % (k, med, float(np.median(curves_all[0])), 100 * np.mean(np.asarray(curves_all[k]) <= 2),
                         100 * np.mean(np.asarray(curves_all[0]) <= 2)))
    for kk in TRANSFORMS:
        v = np.asarray(coord_all[kk])
        out("COORD event position against the tracking ball at the event frame, transform %-13s: median %.2f m, "
            "within 3 m %.0f%% (n %d)" % (kk, float(np.median(v)), 100 * np.mean(v <= 3), len(v)))
    out("")
    for line in inventory_lines(per_match):
        out(line)
    out("[done in %d s]" % (time.time() - t0))
    with open(OUT_INV, "w") as f:
        f.write("\n".join(lines) + "\n")
    print("wrote %s" % os.path.relpath(OUT_INV, HERE))
    return 0


# ------------------------------------------------------------------------------------------------ E0 alignment
OFFSET_RANGE = tuple(range(-100, 101))


def align(events, sections, n_frames, halves, links):
    """E0: [(half, frame)] with the per-half offset applied, and per half (k, median m at k, median m at 0, k from
    open-play passes only, n). halves = the tracking halves (dicts with home, away, ball)."""
    raw = assign_halves(events, sections, n_frames)
    ks, info = {}, []
    for hi in range(len(sections)):
        idx = [i for i, (h, _f) in enumerate(raw) if h == hi]
        es, fs = [events[i] for i in idx], [raw[i] for i in idx]
        cur = player_ball_curve(es, fs, halves, links, OFFSET_RANGE)
        k, med = best_offset(cur)
        sel = [j for j, e in enumerate(es) if e["path"] == "Play/Pass"]
        kp, _mp = best_offset(player_ball_curve([es[j] for j in sel], [fs[j] for j in sel], halves, links,
                                                OFFSET_RANGE))
        ks[hi] = k
        info.append((k, med, float(np.median(cur[0])), kp, len(cur[0])))
    out = []
    for e, (h, _f) in zip(events, raw):
        if h is None:
            out.append((None, None))
        else:
            f = frame_of(e["t"], sections[h][2], ks[h])
            out.append((h, min(max(f, 0), n_frames[h] - 1)))
    return out, info


# ------------------------------------------------------------------------------------------------ E1 situations
SITS = ("KICK-OFF", "THROW-IN", "CORNER", "GOAL KICK", "FREE KICK", "SHOT", "FOUL / OFFSIDE", "CROSS",
        "GOALKEEPER ACTION", "LOOSE BALL / SCRAMBLE", "AERIAL DUEL", "TACKLE LOST / DRIBBLE PAST",
        "GROUND DUEL / TACKLE WON", "LONG BALL / CLEARANCE", "PASS INTERCEPTED", "PASS MISPLACED / OUT",
        "PASS COMPLETED", "BALL TOUCH", "BALL CLAIMED / INTERCEPTION", "OTHER")
NONE_SIT = "NO EVENT WITHIN 2 S"
ADMIN = ("Substitution", "Caution", "CautionTeamofficial", "PlayerNotSentOff", "PenaltyNotAwarded",
         "VideoAssistantAction", "FinalWhistle", "ChanceWithoutShot", "SpectacularPlay", "PossessionLossBeforeGoal",
         "SitterPrevented", "FairPlay", "GoalDisallowed", "Nutmeg", "Run", "OtherPlayerAction")
CONTACT_OPEN = ("Play/Pass", "OtherBallAction", "TacklingGame", "BallClaiming", "BallDeflection")
SCRAMBLE_FRAMES, SCRAMBLE_MIN, SCRAMBLE_SWITCHES = 75, 3, 2
SHOT_OUTCOME = {"SavedShot": "save", "BlockedShot": "block", "ShotWide": "out", "ShotWoodWork": "woodwork",
                "SuccessfulShot": "goal", "OtherShot": "other"}


def is_admin(e):
    return e["path"] in ADMIN


def is_contact(e):
    return e["path"] in CONTACT_OPEN or e["path"].startswith("ShotAtGoal/") or e["path"] == "Play/Cross"


def acting_team(e):
    return e["q"].get("WinnerTeam") if e["path"] == "TacklingGame" else e["q"].get("Team")


def scramble_flags(events, frames):
    """E1 rule 10 per event (events of one half, any order): True if the event is an open-play contact event inside a
    3 s window with >= 3 contact events whose acting teams change at least twice in time order."""
    order = sorted(range(len(events)), key=lambda i: (frames[i], events[i]["t"], i))
    con = [i for i in order if is_contact(events[i])]
    flag = [False] * len(events)
    for a_pos, a in enumerate(con):
        win = [i for i in con[a_pos:] if frames[i] - frames[a] <= SCRAMBLE_FRAMES]
        if len(win) < SCRAMBLE_MIN:
            continue
        teams = [acting_team(events[i]) for i in win if acting_team(events[i])]
        if sum(1 for x, y in zip(teams, teams[1:]) if x != y) >= SCRAMBLE_SWITCHES:
            for i in win:
                if events[i]["path"] in CONTACT_OPEN:
                    flag[i] = True
    return flag


def situation(e, nxt, gk, scramble):
    """E1: the situation of one non-admin event. nxt = the next non-admin event of the half (or None); gk = the acting
    player is a goalkeeper; scramble = scramble_flags' value."""
    p, q = e["path"], e["q"]
    for prefix, name in (("KickOff/", "KICK-OFF"), ("ThrowIn/", "THROW-IN"), ("CornerKick/", "CORNER"),
                         ("GoalKick/", "GOAL KICK"), ("FreeKick/", "FREE KICK"), ("Penalty/", "FREE KICK"),
                         ("ShotAtGoal/", "SHOT")):
        if p.startswith(prefix):
            return name
    if p in ("Foul", "Offside"):
        return "FOUL / OFFSIDE"
    if p == "Play/Cross":
        return "CROSS"
    if (gk and p in ("BallClaiming", "OtherBallAction", "Play/Pass")) or (p == "Play/Pass" and "GoalKeeperAction" in q):
        return "GOALKEEPER ACTION"
    if scramble and p in CONTACT_OPEN:
        return "LOOSE BALL / SCRAMBLE"
    if p == "TacklingGame":
        if q.get("Type") == "air":
            return "AERIAL DUEL"
        return "TACKLE LOST / DRIBBLE PAST" if q.get("WinnerRole") == "withBallControl" else "GROUND DUEL / TACKLE WON"
    if (p == "OtherBallAction" and q.get("DefensiveClearance") == "true") or (p == "Play/Pass"
                                                                               and q.get("Distance") == "long"):
        return "LONG BALL / CLEARANCE"
    if p == "Play/Pass":
        if q.get("Evaluation") == "unsuccessful":
            if (nxt is not None and is_contact(nxt) and acting_team(nxt) and acting_team(e)
                    and acting_team(nxt) != acting_team(e)):
                return "PASS INTERCEPTED"
            return "PASS MISPLACED / OUT"
        return "PASS COMPLETED"
    if p == "OtherBallAction":
        return "BALL TOUCH"
    if p == "BallClaiming":
        return "BALL CLAIMED / INTERCEPTION"
    return "OTHER"


def map_half(events, frames, gk):
    """E1 over one half: [situation or None (admin)] in the events' order."""
    keep = [i for i in sorted(range(len(events)), key=lambda i: (frames[i], events[i]["t"], i))
            if not is_admin(events[i])]
    scr = scramble_flags([events[i] for i in keep], [frames[i] for i in keep])
    out = [None] * len(events)
    for j, i in enumerate(keep):
        nxt = events[keep[j + 1]] if j + 1 < len(keep) else None
        out[i] = situation(events[i], nxt, gk[i], scr[j])
    return out


# ------------------------------------------------------------------------------------------------ E3 errors
LATE_FRAMES, WRONG_FRAMES, NEAR = 25, 50, 75
KINDS = ("MISSED", "FALSE", "LATE END", "WRONG TEAM")


def errors_half(truth, pred):
    """E3: [(kind, anchor frame, detail)] of one half. detail: the new team (MISSED, FALSE), (true end, predicted
    end) (LATE END), (team predicted, length) (WRONG TEAM)."""
    import explore_short_possessions_2 as ex2
    H_, A_ = 0, 1
    truth, pred = np.asarray(truth), np.asarray(pred)
    out = []
    tc = ex2.true_changes(truth)
    cls = ex2.start_classes(truth, pred)
    by_start = {s: c for s, _e, _k, c, _p, _pe in cls}
    for s, k, _d in tc:
        if by_start.get(s) == "MISSED":
            out.append(("MISSED", int(s), int(k)))
    for p, k, _d in ex2.true_changes(pred):
        if not any(k2 == k and abs(s - p) <= NEAR for s, k2, _d2 in tc):
            out.append(("FALSE", int(p), int(k)))
    for s, e, k, c, p, pe in cls:
        if c != "MISSED" and pe - e > LATE_FRAMES:
            out.append(("LATE END", int(e), (int(e), int(pe))))
    wrong = (truth <= A_) & (pred <= A_) & (pred != truth) & (truth >= H_)
    edges = np.flatnonzero(np.diff(np.r_[0, wrong.astype(np.int8), 0]))
    for a, b in zip(edges[::2], edges[1::2]):
        if b - a >= WRONG_FRAMES:
            out.append(("WRONG TEAM", int(a), (int(pred[a]), int(b - a))))
    return out


# ------------------------------------------------------------------------------------------------ E4 tags and prizes
TAG_FRAMES, WIN_BEFORE, WIN_AFTER = 50, 25, 75


def nearest(anchor, ev_frames):
    """Index of the nearest event within TAG_FRAMES of the anchor (ties: the earlier), or None. ev_frames sorted."""
    ev_frames = np.asarray(ev_frames)
    if not len(ev_frames):
        return None
    d = np.abs(ev_frames - anchor)
    i = int(np.argmin(d))                         # argmin returns the first minimum: the earlier event on a tie
    return i if d[i] <= TAG_FRAMES else None


def with_truth(pred, truth, frames, before=WIN_BEFORE, after=WIN_AFTER):
    """E4's P': pred with truth copied into [f - before, f + after) around every frame f (clipped)."""
    out = np.array(pred, copy=True)
    n = len(out)
    for f in frames:
        a, b = max(0, f - before), min(n, f + after)
        out[a:b] = truth[a:b]
    return out


# ------------------------------------------------------------------------------------------------ E5 case files
COL = {"H": "#2a78d6", "A": "#eb6834", "D": "#b9b8b2", "X": "#ffffff"}
INK, INK2, SURFACE, LINE = "#0b0b0b", "#52514e", "#fcfcfb", "#c9c8c2"
LETTER = {0: "H", 1: "A", 2: "D", 3: "X"}
SNAPS = (-1, 0, 1, 2, 3)


def _pitch(ax):
    from matplotlib.patches import Arc, Circle, Rectangle
    ax.add_patch(Rectangle((-L_HALF, -W_HALF), 2 * L_HALF, 2 * W_HALF, fill=False, lw=0.8, ec=LINE))
    ax.plot([0, 0], [-W_HALF, W_HALF], lw=0.8, c=LINE)
    ax.add_patch(Circle((0, 0), 9.15, fill=False, lw=0.8, ec=LINE))
    for sgn in (-1, 1):
        ax.add_patch(Rectangle((sgn * L_HALF - (16.5 if sgn > 0 else 0), -20.16), 16.5, 40.32, fill=False, lw=0.8,
                               ec=LINE))
        ax.add_patch(Rectangle((sgn * L_HALF - (5.5 if sgn > 0 else 0), -9.16), 5.5, 18.32, fill=False, lw=0.8,
                               ec=LINE))
        ax.add_patch(Arc((sgn * (L_HALF - 11), 0), 18.3, 18.3, theta1=127 if sgn > 0 else -53,
                         theta2=233 if sgn > 0 else 53, lw=0.8, ec=LINE))
    ax.set_xlim(-L_HALF - 2, L_HALF + 2)
    ax.set_ylim(-W_HALF - 2, W_HALF + 2)
    ax.set_aspect("equal")
    ax.axis("off")


def render_case(path, home, away, ball, truth, pred, f0, title, marked=None, events=()):
    """One case file: 5 snapshots (SNAPS seconds from frame f0) and a timeline (-5 to +10 s). home, away (T, n, 2),
    ball (T, 2), truth and pred (T,) labels 0-3 of one half; marked = ("H" | "A", column) of the event's player;
    events = [(frame, short label)] drawn on the timeline. Returns the snapshot frames."""
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt
    from matplotlib.patches import Patch, Rectangle
    T = len(truth)
    fig = plt.figure(figsize=(17, 5.6), dpi=100, facecolor=SURFACE)
    gs = fig.add_gridspec(2, 5, height_ratios=(3.4, 1.0), hspace=0.28, wspace=0.04, left=0.02, right=0.99,
                          top=0.87, bottom=0.09)
    fig.suptitle(title, fontsize=11, color=INK, x=0.02, ha="left")
    shown = []
    for c, k in enumerate(SNAPS):
        f = min(max(f0 + k * FPS, 0), T - 1)
        shown.append(f)
        ax = fig.add_subplot(gs[0, c])
        ax.set_facecolor(SURFACE)
        _pitch(ax)
        for xy, key in ((home, "H"), (away, "A")):
            p = np.asarray(xy[f], float)
            ok = np.all(np.isfinite(p), axis=1)
            ax.scatter(p[ok, 0], p[ok, 1], s=34, c=COL[key], edgecolors=SURFACE, linewidths=1.0, zorder=3)
        if marked is not None:
            xy = home if marked[0] == "H" else away
            p = np.asarray(xy[f, marked[1]], float)
            if np.all(np.isfinite(p)):
                ax.scatter([p[0]], [p[1]], s=150, facecolors="none", edgecolors=INK, linewidths=1.6, zorder=4)
        tail = np.asarray(ball[max(0, f - FPS):f + 1], float)
        tail = tail[np.all(np.isfinite(tail), axis=1)]
        if len(tail) > 1:
            ax.plot(tail[:, 0], tail[:, 1], c=INK2, lw=1.2, zorder=4)
        b = np.asarray(ball[f], float)
        if np.all(np.isfinite(b)):
            ax.scatter([b[0]], [b[1]], s=26, c=INK, edgecolors=SURFACE, linewidths=1.2, zorder=5)
        lt, lp = LETTER[int(truth[f])], LETTER[int(pred[f])]
        ax.set_title("%+d s   truth %s   v1.4 %s%s" % (k, lt, lp, "" if lt == lp else "   (differ)"), fontsize=10,
                     color=INK, pad=3)
    ax = fig.add_subplot(gs[1, :])
    ax.set_facecolor(SURFACE)
    lo, hi = f0 - 5 * FPS, f0 + 10 * FPS
    for row, lab in ((1, truth), (0, pred)):
        for f in range(max(lo, 0), min(hi, T)):
            ax.add_patch(Rectangle(((f - f0) / FPS, row + 0.08), 1 / FPS, 0.84, color=COL[LETTER[int(lab[f])]], lw=0))
    for k in SNAPS:
        ax.axvline(k, c=INK2, lw=0.6, ls=":", zorder=3)
    for f, text in events:
        if lo <= f < hi:
            x = (f - f0) / FPS
            ax.plot([x, x], [-0.35, 0.0], c=INK, lw=1.0)
            ax.text(x, -0.42, text, fontsize=7, color=INK2, rotation=0, ha="center", va="top")
    ax.set_xlim(-5, 10)
    ax.set_ylim(-1.0, 2.0)
    ax.set_yticks([0.5, 1.5])
    ax.set_yticklabels(["v1.4-dev", "truth"], fontsize=9, color=INK)
    ax.set_xticks(range(-5, 11))
    ax.tick_params(axis="x", labelsize=8, colors=INK2)
    for sp in ax.spines.values():
        sp.set_visible(False)
    ax.legend(handles=[Patch(color=COL["H"], label="H (home)"), Patch(color=COL["A"], label="A (away)"),
                       Patch(color=COL["D"], label="D (dead)")], loc="upper right", bbox_to_anchor=(1.0, 1.32),
              ncol=3, fontsize=8, frameon=False)
    fig.savefig(path, facecolor=SURFACE, metadata={"Software": None})
    plt.close(fig)
    return shown


def pick_examples(cands, n=6, seed=96):
    """E5: cands = [(match, ...)] -> up to n of them: matches shuffled, then round robin, one random candidate per
    match per round."""
    rng = np.random.default_rng(seed)
    by = defaultdict(list)
    for c in cands:
        by[c[0]].append(c)
    order = [sorted(by)[i] for i in rng.permutation(len(by))]
    pools = {m: list(by[m]) for m in order}
    out = []
    while len(out) < n and any(pools.values()):
        for m in order:
            if pools[m] and len(out) < n:
                out.append(pools[m].pop(int(rng.integers(len(pools[m])))))
    return out


def slug(sit):
    import re
    return re.sub(r"[^a-z0-9]+", "_", sit.lower()).strip("_")


SHORT = {"KICK-OFF": "KO", "THROW-IN": "TI", "CORNER": "CK", "GOAL KICK": "GK", "FREE KICK": "FK", "SHOT": "SHOT",
         "FOUL / OFFSIDE": "FOUL", "CROSS": "CROSS", "GOALKEEPER ACTION": "KEEPER", "LOOSE BALL / SCRAMBLE": "LOOSE",
         "AERIAL DUEL": "AIR", "TACKLE LOST / DRIBBLE PAST": "DRIB", "GROUND DUEL / TACKLE WON": "TACKLE",
         "LONG BALL / CLEARANCE": "LONG", "PASS INTERCEPTED": "P-INT", "PASS MISPLACED / OUT": "P-OUT",
         "PASS COMPLETED": "PASS", "BALL TOUCH": "TOUCH", "BALL CLAIMED / INTERCEPTION": "CLAIM", "OTHER": "OTHER"}


def what_went_wrong(errs, f0):
    """One plain line from the errors [(kind, anchor, detail)] tagged to an occurrence at frame f0."""
    parts = []
    for kind, a, det in errs:
        t = (a - f0) / FPS
        if kind == "MISSED":
            parts.append("missed the change to %s at %+.1f s" % (LETTER[det], t))
        elif kind == "FALSE":
            parts.append("false switch to %s at %+.1f s" % (LETTER[det], t))
        elif kind == "LATE END":
            parts.append("possession ended %.1f s late (true end %+.1f s)" % ((det[1] - det[0]) / FPS, t))
        else:
            parts.append("wrong team (%s) for %.1f s from %+.1f s" % (LETTER[det[0]], det[1] / FPS, t))
    return "; ".join(parts)


