def _zone(ball_x, g_team):
    """Own / middle / final third of the acting team (g_team = +1 when its own goal is at x = +52.5)."""
    if g_team is None or not np.isfinite(ball_x):
        return "unknown"
    xa = -g_team * ball_x
    return "own third" if xa < -17.5 else ("final third" if xa > 17.5 else "middle third")


