import harness  # noqa: E402  (m1, _f_tuple, _pseudo_truth, features, run_method, paired, labels, matches, _score_match)
import l1a_measure as l1a  # noqa: E402  (_masked, team_logE, A_TEAM, BIG, dec: the calls of predict_m1)
import possession_metrics as pm  # noqa: E402  (possession_spells; on the path through external_harness_v2)
import possession_v1_0 as pv  # noqa: E402  (C_DIGEST, MEAN_0030)

H, A, D, FPS = harness.H, harness.A, harness.D, harness.FPS
GRID = (25, 50, 100, 150, 250)                  # eps = 1/k
CURRENT = 150
CELLS = ((2.0, "A"), (3.0, "A"), (2.0, "D"), (3.0, "D"))
SELECT_CELL = (2.0, "A")
MIN_GAIN, MAX_D_DROP, MIN_FOLDS, TOL = 0.010, 0.010, 5, 1e-9
FRAMES_PER_MINUTE = 60 * FPS
OUT_RUN = os.path.join(HERE, "claude_reports", "0044_part1_run.txt")


# ------------------------------------------------------------------------------------------------ W0
def decode_half_eps(fs, eps):
    """harness.m1 (l1a_measure.predict_m1) with the Viterbi's switching setting eps passed through: codes 0 H, 1 A,
    2 D (int8). A larger eps makes a team switch cheaper (W0)."""
    dh, da = l1a._masked(harness._f_tuple(fs), fs["ball_visible"])
    logE = l1a.team_logE(dh, da, l1a.A_TEAM)
    dead = harness._pseudo_truth(fs) == D
    logE[dead, H] = -l1a.BIG
    logE[dead, A] = -l1a.BIG
    logE[:, D] = np.where(dead, 0.0, -l1a.BIG)
    return l1a.dec.viterbi(logE, eps).astype(np.int8)


def method_of(k):
    return lambda fs: decode_half_eps(fs, 1 / k)


def switch_cost(k):
    """c(1/k) = log((1 - 2 eps) / eps), the price of one switch in nats."""
    return math.log(k - 2)


# ------------------------------------------------------------------------------------------------ W3
def possession_lengths(halves):
    """Frame lengths of the possessions (maximal H or A runs) of each half, never across two halves."""
    out = []
    for c in halves:
        out += [b - a for a, b, _k in pm.possession_spells(np.asarray(c, np.int8), [(0, len(c))])]
    return out


def rate_of(by_match):
    """(possessions per graded minute, lengths) over {match: [halves]}; every frame of a half is a graded minute."""
    lengths, frames = [], 0
    for halves in by_match.values():
        lengths += possession_lengths(halves)
        frames += sum(len(c) for c in halves)
    return len(lengths) / (frames / FRAMES_PER_MINUTE), lengths


def median_s(lengths):
    return float(np.median(lengths)) / FPS if lengths else float("nan")


# ------------------------------------------------------------------------------------------------ W4
def select(scores, ids):
    """The k of the highest mean of scores[k][mid] over ids; ties to 150, then to the nearest switching cost."""
    ids = sorted(ids)
    means = {k: float(np.mean([scores[k][m] for m in ids])) for k in GRID}
    best = max(means.values())
    tied = [k for k in GRID if means[k] == best]
    if CURRENT in tied:
        return CURRENT
    return min(tied, key=lambda k: abs(switch_cost(k) - switch_cost(CURRENT)))


def folds(scores, ids):
    return {m: select(scores, [x for x in ids if x != m]) for m in sorted(ids)}


# ------------------------------------------------------------------------------------------------ W5
def adopt(lomo_a, d_drop, k_star, n_folds):
    """(adopt?, failed conditions). lomo_a = {merge: (diff, lo)} in regime A; d_drop = {merge: mean(eps*) -
    mean(1/150)} in regime D; n_folds = folds that chose k_star."""
    failed = []
    for merge in (2.0, 3.0):
        diff, lo = lomo_a[merge]
        if not (diff >= MIN_GAIN - TOL and lo > 0):
            failed.append("(a) A %d s" % merge)
    for merge in (2.0, 3.0):
        if not d_drop[merge] >= -MAX_D_DROP - TOL:
            failed.append("(b) D %d s" % merge)
    if n_folds < MIN_FOLDS:
        failed.append("(c) folds %d of 7" % n_folds)
    if k_star == CURRENT:
        failed.append("(d) eps* is 1/%d" % CURRENT)
    return not failed, failed


def verdict_line(ok, k_star, failed):
    if ok:
        return "VERDICT SWITCHING: ADOPT eps* = 1/%d" % k_star
    return "VERDICT SWITCHING: KEEP 1/%d (failed: %s)" % (CURRENT, ", ".join(failed))


# ------------------------------------------------------------------------------------------------ the study
def study():
    import time
    import warnings
    import core_breakdown as cb
    import core_edge_tails as et
