import re
import sys
from collections.abc import Mapping

import numpy as np

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
import ceiling  # noqa: E402
import l1a_measure as l1a  # noqa: E402

eh = l1a.eh
H, A, D, FPS = l1a.H, l1a.A, l1a.D, l1a.FPS
