import l1a_measure as l1a  # noqa: E402  (_masked, eh)
import learned_evidence as le  # noqa: E402  (table, fit, decode_learned, COLS, SUB)

H, A, D, FPS = harness.H, harness.A, harness.D, harness.FPS
WINDOWS = (25, 50, 75)
CONTACT_M, FIRST_M, CROWD_M, DUEL_M = 1.5, 1.0, 5.0, 1.0
FUT_NAMES = ("VISIBLE_SHARE", "CONTACT_SHARE", "MIN_D", "FIRST_CONTACT", "CROWD", "WIDTH_CHANGE", "HULL_CHANGE",
             "PRESS_W", "DUEL_SHARE")
PAST_NAMES = tuple(c for c in FUT_NAMES if c != "FIRST_CONTACT")
NEW_COLS = tuple("%s%d_%s" % (d, w, c) for w in WINDOWS for d, names in (("F", FUT_NAMES), ("P", PAST_NAMES))
                 for c in names)
