    if len(shown):
        ls = int(shown[-1])
        out[0] = min(c - ls, 150)
        bx, by = ball[ls]
        out[1], out[2] = abs(by) - HY, abs(bx) - HX
        out[3] = min(HY - abs(by), HX - abs(bx))
