def rows(ball, vis, home, away, cands):
    """report 0261's D2 rows: Q at the candidate's start, its length, frames to the next sighting (capped 150), the
    two source flags and the line distance."""
    ball_ = np.asarray(ball, float)[:, :2]
    v = np.asarray(vis, bool) & np.isfinite(ball_).all(axis=1)
