def visible_share(vis, t):
    return float(np.mean(vis[max(0, t - VIS_HALF):min(len(vis), t + VIS_HALF + 1)]))


def shorter_adjacent(lab, t, segs=None):
    """Seconds of the shorter of the run ending at t and the run starting at t."""
    segs = ceiling.segs_of(lab) if segs is None else segs
    starts = np.array([s for s, _e, _c in segs], int)
    k = int(np.searchsorted(starts, t, side="right")) - 1
    return min(segs[k][1] - segs[k][0], segs[k - 1][1] - segs[k - 1][0]) / FPS


def _record(h, t, new, lab, segs, diff):
    m = margin(diff, t)
    return dict(vis=visible_share(h["vis"], t), sign=has_sign(m, new), shorter=shorter_adjacent(lab, t, segs),
                contested=contested(h["vis"], h["dh"], h["da"], t), dead=bool(h["dead"][t]))


def anatomy_half(h):
    """(records of the true direct hand-overs with their class, records of the false switches) for one half."""
    tb, pb_ = l1a.boundaries(h["truth"]), l1a.boundaries(h["pred"])
    diff = evidence_diff(h["dh"], h["da"])
    ts, ps = ceiling.segs_of(h["truth"]), ceiling.segs_of(h["pred"])
    rec = [dict(_record(h, t, to, h["truth"], ts, diff), **{"class": classify((t, f, to), pb_)}) for t, f, to in tb]
    fal = [_record(h, p, to, h["pred"], ps, diff) for p, f, to in pb_ if is_false((p, f, to), tb)]
    return rec, fal, len(pb_)


def _stats(recs, denom):
    c = [r["contested"] for r in recs if r["contested"] is not None]
    return dict(n=len(recs), share=len(recs) / denom if denom else float("nan"),
                vis=float(np.median([r["vis"] for r in recs])) if recs else float("nan"),
                n_sign=sum(r["sign"] for r in recs),
                sign=sum(r["sign"] for r in recs) / len(recs) if recs else float("nan"),
                shorter=float(np.median([r["shorter"] for r in recs])) if recs else float("nan"),
                n_cont=sum(c), n_vis_t=len(c), cont=sum(c) / len(c) if c else float("nan"),
                dead=sum(r["dead"] for r in recs) / len(recs) if recs else float("nan"))


def anatomy(data):
    rec, fal, n_pred = [], [], 0
    for m in sorted(data):
        for h in data[m]:
            r, f, k = anatomy_half(h)
            rec += r; fal += f; n_pred += k
    out = {c: _stats([r for r in rec if r["class"] == c], len(rec)) for c in ("HIT", "NEAR", "MISSED")}
    out["FALSE"] = _stats(fal, n_pred)
    out["n_true"], out["n_pred"] = len(rec), n_pred
    return out


def _f(v, fmt):
    return "n/a" if np.isnan(v) else fmt % v


def anatomy_lines(a, label):
    out = ["ANATOMY %s | true direct hand-overs %d | predicted direct switches %d" % (label, a["n_true"], a["n_pred"])]
    for c in ("HIT", "NEAR", "MISSED", "FALSE"):
        s = a[c]
        out.append("ANATOMY %s | %-6s | n %4d | share %s%s | median visible share %s | new team's sign %s | median "
                   "shorter adjacent %s s | contested %s (%d of %d visible at t) | dead at t %s"
                   % (label, c, s["n"], _f(s["share"], "%.3f"), " of predicted" if c == "FALSE" else "",
                      _f(s["vis"], "%.3f"), _f(s["sign"], "%.3f"), _f(s["shorter"], "%.2f"), _f(s["cont"], "%.3f"),
                      s["n_cont"], s["n_vis_t"], _f(s["dead"], "%.3f")))
    return out


def tables(data, label, with_anatomy=True):
    """The budget lines (and the anatomy lines) of one cell; T6 builds them twice."""
    b = budget(data)
    lines = budget_lines(b, label)
    if with_anatomy:
        lines += anatomy_lines(anatomy(data), label)
    return lines


# ------------------------------------------------------------------------------------------------ G4 predictions
def p1(g_missing, g_all):
    return g_missing >= 0.5 * g_all - TOL


def p2(g_restart):
    return g_restart >= 0.030 - TOL


def p3(g_short, g_all):
    return g_short >= 0.40 * g_all - TOL


def p4(vis_hit, vis_missed):
    return bool(vis_hit - vis_missed >= 0.20 - TOL)          # an empty row (NaN) fails


def p5(n_sign, n_missed):
    return n_missed > 0 and n_sign / n_missed <= 0.50 + TOL


def _verdict(ok):
    return "HELD" if ok else "FAILED"


def _captured(g, g_all):
    return "%.3f" % (g / g_all) if g_all != 0 else "n/a"


def prediction_lines(b, a):
    g = {k: b["rows"][k]["gain"] for k in ROWS}
    hit, mis = a["HIT"], a["MISSED"]
    return [
        "P1 %s: S_MISSING gain %+.4f against half of S_ALL's %+.4f (captured %s; needs >= 0.500)"
        % (_verdict(p1(g["MISSING"], g["ALL"])), g["MISSING"], g["ALL"], _captured(g["MISSING"], g["ALL"])),
        "P2 %s: S_RESTART gain %+.4f (needs >= +0.030)" % (_verdict(p2(g["RESTART"])), g["RESTART"]),
        "P3 %s: S_SHORT gain %+.4f against 40 percent of S_ALL's %+.4f (captured %s; needs >= 0.400)"
        % (_verdict(p3(g["SHORT"], g["ALL"])), g["SHORT"], g["ALL"], _captured(g["SHORT"], g["ALL"])),
        "P4 %s: median visible share HIT %s, MISSED %s, difference %s (needs >= 0.20)"
        % (_verdict(p4(hit["vis"], mis["vis"])), _f(hit["vis"], "%.3f"), _f(mis["vis"], "%.3f"),
           _f(hit["vis"] - mis["vis"], "%+.3f")),
        "P5 %s: new team's sign in %d of %d MISSED hand-overs, %s (needs <= 0.500)"
        % (_verdict(p5(mis["n_sign"], mis["n"])), mis["n_sign"], mis["n"], _f(mis["sign"], "%.3f")),
    ]


def summary_lines(b):
    r = b["rows"]
    ranked = sorted(NAMED, key=lambda k: -r[k]["gain"])     # stable: an exact tie keeps NAMED's order
    out = ["BUDGET SUMMARY (merge 2 s, regime A, dead = C)", "S_ALL gain %+.4f" % r["ALL"]["gain"]]
    out += ["%d. S_%s gain %+.4f; %s per percent of live frames" % (i + 1, k, r[k]["gain"], _per_text(r[k]["per"]))
            for i, k in enumerate(ranked)]
    return out


# ------------------------------------------------------------------------------------------------ the study
def cell_data(C, merge, regime):
    """{match: [half dicts]} with the merged truth, C, the decoder's labels and the regime's ball and distances (G0)."""
    data = {}
    for mid in sorted(harness.matches()):
        truths = harness.labels(mid, merge)
        fss = harness.features(mid, merge, regime, ("mask", C))
        preds = harness.run_method(hs.method_of(150), mid, merge, regime, ("mask", C))
        data[mid] = [dict(truth=t, dead=np.asarray(fs["dead"], bool), pred=p, vis=np.asarray(fs["ball_visible"], bool),
                          dh=fs["dh"], da=fs["da"]) for t, fs, p in zip(truths, fss, preds)]
    return data


def label_of(cell):
    return "%d s %s" % (cell[0], cell[1])


def study():
    import time
    import warnings
    import core_breakdown as cb
    import core_edge_tails as et
    lines = []

    def out(s=""):
        print(s, flush=True)
        lines.append(s)
    t0 = time.time()
    out("REPORT 0045: possession error budget on the 7 public DFL matches (rules G0-G9; research only)")
    with warnings.catch_warnings():
        warnings.simplefilter("ignore")
        rep = et.reproduce(lambda s: out("[" + s + "]" if "[" in s else s))
        if rep is None or cb.digest(rep[3]) != pv.C_DIGEST:
            out("STOP: C does not reproduce")
            return _finish(lines, 1)
        C = rep[3]
        out("C digest equals report 0025's (a90b07e7...9596): PASS")
        data = {cell: cell_data(C, *cell) for cell in CELLS}
        out("[decoded %d cells in %d s]" % (len(CELLS), time.time() - t0))
        p = data[PRIMARY]
        mean = float(np.mean([harness._score_match([h["truth"] for h in p[m]], [h["pred"] for h in p[m]])
                              for m in sorted(p)]))
        if round(mean, 4) != B2_MEAN:
            out("STOP: B2 fails (decoder mean %.4f, report 0044 0.4350)" % mean)
            return _finish(lines, 1)
        out("B2 PASS: decoder mean in the primary cell (merge 2 s, regime A, dead = C) %.4f (report 0044: 0.4350)" % mean)
        d_empty = d_all = d_dead = n = 0
        for cell in CELLS:
            for m in sorted(data[cell]):
                for h in data[cell][m]:
                    e = oracle(h["pred"], h["truth"], h["dead"], np.zeros(len(h["truth"]), bool))
                    a = oracle(h["pred"], h["truth"], h["dead"], ~h["dead"])
                    d_empty += int(np.sum(e != h["pred"]))
                    d_all += int(np.sum(a != truth_teams_on_mask(h["pred"], h["truth"], h["dead"])))
                    d_dead += int(np.sum((a == D) != (h["pred"] == D)))
                    n += len(h["truth"])
        ok = d_empty == 0 and d_all == 0 and d_dead == 0
        out("T1 PUBLIC %s: differing frames, O_empty vs decoder %d; O_S_ALL vs truth teams on mask C %d; D changed %d "
            "(over %d frames, 3 cells x 14 halves)" % ("PASS" if ok else "FAIL", d_empty, d_all, d_dead, n))
        budgets = {}
        for cell in CELLS:
            out("")
            budgets[cell] = budget(data[cell])
            for s in budget_lines(budgets[cell], label_of(cell)):
                out(s)
        out("")
        a = anatomy(p)
        for s in anatomy_lines(a, label_of(PRIMARY)):
            out(s)
        out("")
        for s in prediction_lines(budgets[PRIMARY], a):
            out(s)
        out("")
        for s in summary_lines(budgets[PRIMARY]):
            out(s)
    out("[done in %d s]" % (time.time() - t0))
    return _finish(lines, 0)


def _finish(lines, code):
    with open(OUT_RUN, "w") as f:
        f.write("\n".join(lines) + "\n")
    print("wrote %s" % os.path.relpath(OUT_RUN, HERE))
    return code


def main(argv=None):
    argv = sys.argv[1:] if argv is None else argv
    if argv:
        sys.exit("possession_budget_public: takes no arguments")
    return study()


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
