def complete_possessions(truth):
    """[(start, stop, team, context)] of complete possessions (not touching the half's ends); context RESTART when
    the frame before is D, OPEN when it is the other team."""
    truth = np.asarray(truth, np.int8)
    n = len(truth)
    out = []
    for a, b, k in pm.possession_spells(truth, [(0, n)]):
        if a == 0 or b == n:
            continue
        out.append((a, b, int(k), "RESTART" if truth[a - 1] == D else "OPEN"))
    return out


def n_censored(truth):
    n = len(truth)
    return sum(1 for a, b, _k in pm.possession_spells(np.asarray(truth, np.int8), [(0, n)]) if a == 0 or b == n)


def third_of(ball, t, g):
    """OWN, MIDDLE, ATTACKING or UNKNOWN from the ball's x at frame t (or the nearest frame within 25 with a ball),
    oriented by the team's own-goal sign g."""
    ball = np.asarray(ball, float)
    n = len(ball)
    for d in range(BALL_SEARCH + 1):
        for u in ((t,) if d == 0 else (t - d, t + d)):
            if 0 <= u < n and np.isfinite(ball[u, 0]):
                own = g * ball[u, 0]
                return "OWN" if own > PITCH_L / 6 else ("ATTACKING" if own < -PITCH_L / 6 else "MIDDLE")
    return "UNKNOWN"


def records(merge):
    """{match: [(length frames, team, context, third)]} of complete possessions at a merge level."""
    out, cens = {}, 0
    for mid in sorted(harness.matches()):
        m = harness.matches()[mid]
        out[mid] = []
        for hi, (t, h) in enumerate(zip(harness.labels(mid, merge), m["halves"])):
            cens += n_censored(t)
            d = rs.direction(h["home"], h["away"])
            for a, b, k, ctx in complete_possessions(t):
                g = None if d is None else (d[0] if k == H else d[1])
                third = "UNKNOWN" if g is None else third_of(h["ball"], a, g)
                out[mid].append((b - a, k, ctx, third))
