# ------------------------------------------------------------------------------------------------ L4 fits
def fit(family, x):
    x = np.asarray(x, float)
    mu = float(np.mean(x))
    if family == "GEOM":
        return ("GEOM", 1.0 / (1.0 + mu))
    if family == "NB":
        best = None
        for r in range(1, R_MAX + 1):
            q = r / (r + mu)
            ll = float(np.sum(loglik_nb(x, r, q)))
            if best is None or ll > best[0]:
                best = (ll, r, q)
        return ("NB", best[1], best[2])
    from scipy import stats
    y = x + 0.5
    if family == "LOGN":
        s, _loc, scale = stats.lognorm.fit(y, floc=0)
        return ("LOGN", s, scale)
    a, _loc, scale = stats.gamma.fit(y, floc=0)
    return ("GAMMA", a, scale)


def loglik_nb(x, r, q):
    from scipy.special import gammaln
    x = np.asarray(x, float)
    return gammaln(x + r) - gammaln(r) - gammaln(x + 1) + r * np.log(q) + x * np.log1p(-q)


def loglik(params, x):
    """Per-observation log-probabilities on x = 0, 1, 2, ... (continuous families discretised as F(x+1) - F(x))."""
    x = np.asarray(x, float)
    fam = params[0]
    if fam == "GEOM":
        p = params[1]
        return np.log(p) + x * np.log1p(-p)
    if fam == "NB":
        return loglik_nb(x, params[1], params[2])
    from scipy import stats
    dist = stats.lognorm(params[1], scale=params[2]) if fam == "LOGN" else stats.gamma(params[1], scale=params[2])
    pr = dist.cdf(x + 1) - dist.cdf(x)
    return np.log(np.maximum(pr, 1e-300))


def params_text(p):
    if p[0] == "GEOM":
        return "GEOM p %.5f" % p[1]
    if p[0] == "NB":
        return "NB r %d q %.5f" % (p[1], p[2])
    return "%s shape %.4f scale %.2f" % p


def heldout(groups_x, family):
    """{match: (sum LL, n)} with each match held out: fit on the other matches' pooled x. groups_x {match: x array}."""
    out = {}
    for m in sorted(groups_x):
        train = np.concatenate([groups_x[o] for o in sorted(groups_x) if o != m])
        p = fit(family, train)
        ll = loglik(p, groups_x[m])
        out[m] = (float(np.sum(ll)), len(groups_x[m]))
    return out


def heldout_split(xs_by_group, family):
    """{match: sum LL} where each held-out possession is scored with its own group's fit (fit in-fold per group).
    xs_by_group {group: {match: x array}}."""
    tot = {}
    for g, by_m in xs_by_group.items():
        for m, (ll, _n) in heldout(by_m, family).items():
            tot[m] = tot.get(m, 0.0) + ll
    return tot


def gain_percent(ll_split, ll_pooled):
    return (ll_split - ll_pooled) / abs(ll_pooled) * 100.0


