def describe(lengths, m0):
    L = np.asarray(lengths, float) / FPS
    if not len(L):
        return "n 0"
    dec = np.percentile(L, np.arange(10, 100, 10))
    edges = [m0 / FPS] + list(BINS_S) + [np.inf]
    hist = [float(np.mean((L >= lo) & (L < hi))) for lo, hi in zip(edges[:-1], edges[1:])]
    return ("n %d | mean %.2f s | deciles %s s | hist %s" % (len(L), float(np.mean(L)), " ".join("%.2f" % v for v in dec),
                                                        " ".join("%.3f" % v for v in hist)))


def study():
    import time
