def stage_rows(home, away, ball, vis, positions, kick=0, sig=None):
    """{key: PB row} at the given frames {key: frame}: edges_v1_7.edge_rows' construction at any frame (v2.2)."""
    import warnings
    import edge_regression as eg
    home, away = np.asarray(home, float), np.asarray(away, float)
    n = len(home)
    with warnings.catch_warnings():
        warnings.simplefilter("ignore")
        sig = ev.signals_of(home, away, kick) if sig is None else sig
        bc = np.asarray(eg.ball_columns(np.asarray(ball, float), np.asarray(vis, bool),
                                        np.concatenate([home, away], axis=1)), float)
        rows = {}
        for k, c in positions.items():
            fr = [min(max(int(c) + o, 0), n - 1) for o in eg.OFFS]
            rows[k] = np.concatenate([eg.player_columns(sig, fr).ravel(), bc[fr].ravel()])
    return rows, sig


def staged_offsets(stages, home, away, ball, vis, dead, kick=0):
    """{(type, c): o1 + ... + ok}: each stage's rounded prediction at the clipped position after the earlier stages."""
    rows = ev.edge_rows(home, away, ball, vis, dead, kick)
    n = len(np.asarray(dead))
    total = {k: 0 for k in rows}
    pos = {k: k[1] for k in rows}
    sig = None
    for j, models in enumerate(stages):
        if j > 0:
            rows, sig = stage_rows(home, away, ball, vis, pos, kick, sig)
        off = ev.predict(models, rows)
        for k, o in off.items():
            total[k] += o
            pos[k] = min(max(pos[k] + o, 0), n - 1)
    return total


def edge_step(edges_models, home, away, b2, vis, dead_c, kick=0, fixed=None):
    """v2.2's edge step: (new dead frames, gate (n, frozen, open), frames changed). A dict with "stages" = GEH3's three
    stages; any other model dict = v2.1's single-stage edge step (edges_v1_7.edges_block)."""
    if not (isinstance(edges_models, dict) and "stages" in edges_models):
        return p21.edge_step(edges_models, home, away, b2, vis, dead_c, kick, fixed)
    dead = np.asarray(dead_c, bool)
    g = ev.gate(b2, vis, dead)
    if not g[2]:
        return dead.copy(), g, 0
    pred = staged_offsets(edges_models["stages"], home, away, b2, vis, dead, kick)
    new = ev.corrected_mask(dead, ev.long_runs(dead), pred, fixed)
    return new, g, int(np.sum(new != dead))


def decode_block(fs, players, shapes, ball, config, l13_model=None, la_model=None, u_model=None, reader=None, kick=0,
                 flip_model=None, evid_model=None, reader20=None, edges_models=None, fixed=None):
    """possession_v2_1.decode_block with v2.2's edge step (OFF = v2.0; GEH / GE = v2.1's; GEH3 = three stages)."""
    import contest_integration as ci
    import harness
    import learned_evidence as le
    import lookahead_evidence as la
    import night4_pitch as npc
    import possession_v1_5 as p15
    import possession_v1_6 as p16
    import possession_v2_0 as p20
    import restart_shape_public as rs
    if config == "OFF":
        got = p20.decode_block(fs, players, shapes, ball, "PC", l13_model, la_model, u_model, reader, kick, flip_model,
                               evid_model, reader20)
        return tuple(got) + (np.asarray(fs["dead"], bool).copy(), p21.NO_GATE, 0)
    f2, b2, w, sm = p15.gate_and_deblur(fs, ball)
    tab = la.la_table(f2, players, b2, shapes)
    home, away = np.asarray(f2["home_xy"], float), np.asarray(f2["away_xy"], float)
    d = rs.direction(home[kick:kick + rs.DIR_FRAMES], away[kick:kick + rs.DIR_FRAMES])
    pc, _imp = npc.pc_columns(np.asarray(b2, float), np.asarray(f2["ball_visible"], bool), home, away,
                              np.asarray(f2["dead"], bool))
    lo = p20.pc_lo(evid_model, tab, p16.flip_cols(home, away, d), pc)
    contests, rows = p16.contest_rows(f2, b2, tab, shapes, kick)
    probs = reader20.predict_proba(p20.reader_rows(contests, rows, pc))[:, 1] if contests else np.zeros(0)
    lo = ci.apply_contests(lo, contests, probs, p16.THETA, p16.B)
    pushed = int(np.sum((probs >= p16.THETA) | (probs <= 1 - p16.THETA)))
    dead_c = np.asarray(f2["dead"], bool)
    new, g, _ch = edge_step(edges_models, home, away, b2, f2["ball_visible"], dead_c, kick, fixed)    # v2.2
    f3 = harness.Features(f2.match_id, f2.half, dict({k: f2[k] for k in harness.ALLOWED}, dead=new.copy()))
    return le.decode_learned(f3, lo, p21.W_U), w, sm, (len(contests), pushed), new, g, int(np.sum(new != dead_c))


def edges_path(config):
    """The edge model file of a configuration: GEH3 = v2.2's (three stages), GEH = v2.1's, GE = v1.7's."""
    return EDGES22_MODEL if config == "GEH3" else p21.edges_path(config)


