def decode_block(fs, players, shapes, ball, config, l13_model=None, la_model=None, u_model=None, reader=None, kick=0,
                 flip_model=None, evid_model=None, reader20=None, edges_models=None, fixed=None, missed_model=None):
    """possession_v2_4.decode_block's tuple + (bursts, frames re-opened). OFF is possession_v2_4.decode_block WCONV
    itself; SPLIT runs the same steps and splits the dead mask (splitter_v2_5.split) before v2.4's decoder."""
