def decode_block(fs, players, shapes, ball, config, l13_model=None, la_model=None, u_model=None, reader=None, kick=0,
                 flip_model=None, evid_model=None, reader20=None, edges_models=None, fixed=None, missed_model=None):
    """possession_v2_6.decode_block's tuple + ((processed ball, ball shown, v2.5's mask) or None). OFF is
    possession_v2_6.decode_block REOPEN itself; PUSH15 runs the same steps with the contest push at B27."""
    if config == "OFF":                                                                               # v2.7
        return tuple(p26.decode_block(fs, players, shapes, ball, "REOPEN", l13_model, la_model, u_model, reader, kick,
                                      flip_model, evid_model, reader20, edges_models, fixed, missed_model)) + (None,)
    import contest_integration as ci
    import harness
    import lookahead_evidence as la
    import night4_pitch as npc
    import possession_v1_5 as p15
    import possession_v1_6 as p16
    import possession_v2_0 as p20
    import restart_shape_public as rs
    f2, b2, w, sm = p15.gate_and_deblur(fs, ball)
    tab = la.la_table(f2, players, b2, shapes)
    home, away = np.asarray(f2["home_xy"], float), np.asarray(f2["away_xy"], float)
    d = rs.direction(home[kick:kick + rs.DIR_FRAMES], away[kick:kick + rs.DIR_FRAMES])
    pc, _imp = npc.pc_columns(np.asarray(b2, float), np.asarray(f2["ball_visible"], bool), home, away,
                              np.asarray(f2["dead"], bool))
    lo = p20.pc_lo(evid_model, tab, p16.flip_cols(home, away, d), pc)
    contests, rows = p16.contest_rows(f2, b2, tab, shapes, kick)
    probs = reader20.predict_proba(p20.reader_rows(contests, rows, pc))[:, 1] if contests else np.zeros(0)
    lo = ci.apply_contests(lo, contests, probs, p16.THETA, B27)                                       # v2.7
    pushed = int(np.sum((probs >= p16.THETA) | (probs <= 1 - p16.THETA)))
    dead_c = np.asarray(f2["dead"], bool)
    new, g, _ch = p22.edge_step(edges_models, home, away, b2, f2["ball_visible"], dead_c, kick, fixed)
    new, n_st, n_fr = mv.missed_step(missed_model, edges_models["stages"], home, away, b2, f2["ball_visible"], new,
                                     kick)
    new, bursts = spl.split(new, b2, f2["ball_visible"], fixed)                                       # v2.5
    m25 = np.asarray(new, bool).copy()                                                                # v2.7
    new, opened = fst.reopen(new, b2, f2["ball_visible"], fixed)                                      # v2.6
    f3 = harness.Features(f2.match_id, f2.half, dict({k: f2[k] for k in harness.ALLOWED}, dead=new.copy()))
    return (p24.decode_w(f3, lo), w, sm, (len(contests), pushed), new, g, int(np.sum(new != dead_c)),
            (n_st, n_fr), (len(bursts), int(sum(b - a for a, b in bursts))),
            (len(opened), int(sum(b - a for a, b in opened))),
            (np.asarray(b2, float), np.asarray(f2["ball_visible"], bool), m25))                         # v2.7


def push_values(dec, dec24, n_graded):
    """report 0365 K3 P1-P4 on the frames whose label differs from v2.6's (both share one dead mask); a share with
    no frame to count is NaN, which band_word reads as outside the band (RISK)."""                     # v2.7
    n_ch = runs = live = shown = inbox = 0
    for d, d6 in zip(dec, dec24):
        ch = np.asarray(d[0]) != np.asarray(d6[0])
        b2, vis, _m25 = d[10]
        live += int(np.sum(~np.asarray(d[4], bool)))
        n_ch += int(ch.sum())
        runs += int(np.sum(np.diff(np.r_[0, ch.astype(np.int8), 0]) == 1))
        sh = ch & vis
        shown += int(sh.sum())
        with np.errstate(invalid="ignore"):
            inbox += int(np.sum(sh & (np.abs(b2[:, 0]) >= BOX_X) & (np.abs(b2[:, 1]) <= BOX_Y)))
    p1 = 100.0 * n_ch / max(1, n_graded)
    p2 = runs * p11.FRAMES_PER_MINUTE / max(1, live)
    p3 = inbox / shown if shown else float("nan")
    p4 = shown / n_ch if n_ch else float("nan")
    return p1, p2, p3, p4


