def k3_values(dec, dec27, n_graded):
    """report 0392 K3 on UNI against v2.7 (OFF, decoded in the same run): Q1 frames whose label differs (percent of
    graded frames), Q2 the share of predicted restarts that set-up mode extended, Q3 the mean extension in seconds per
    extended restart, Q4 the share of extended frames with the ball shown; NaN (outside any band) when nothing counts."""
    n_ch = ext = n_ext = n_res = ext_shown = 0
    for d, d7 in zip(dec, dec27):
        n_ch += int(np.sum(np.asarray(d[0]) != np.asarray(d7[0])))
        e = d[11]
