import short_possession_public as sp  # noqa: E402  (auc)

H, A, D = harness.H, harness.A, harness.D
EXTRA = ("PRESS_1s", "PRESS_LAG", "ADVANCE_3s")
NEAR_P = 0.5
LAG = (50, 150)
OUT_RUN = os.path.join(HERE, "claude_reports", "0065_run.txt")


# ------------------------------------------------------------------------------------------------ U1, U2
def convergence_point(xy, speed):
    """(T, 2): the speed-weighted mean of the 4 fastest players per frame (NaN when fewer than 4 have a speed)."""
    T = len(xy)
    P = np.full((T, 2), np.nan)
    sp_ = np.where(np.isfinite(speed), speed, -1.0)
    order = np.argsort(-sp_, axis=1, kind="stable")[:, :4]
    rows = np.arange(T)[:, None]
    s4 = sp_[rows, order]
    ok = (np.sum(sp_ >= 0, axis=1) >= 4) & np.all(s4 >= 0, axis=1) & (s4.sum(axis=1) > 0)
    w = np.where(s4 >= 0, s4, 0.0)
    pts = xy[rows, order]
    num = (w[:, :, None] * pts).sum(axis=1)
    P[ok] = num[ok] / w[ok].sum(axis=1)[:, None]
    return P


def press_team(xy, vel, P):
    """(T,): the mean velocity component towards P over the team's present players (those within 0.5 m left out)."""
    import warnings
    d = P[:, None, :] - xy
    dist = np.hypot(d[:, :, 0], d[:, :, 1])
    with np.errstate(invalid="ignore", divide="ignore"):
        comp = (vel * d).sum(axis=2) / dist
    comp = np.where(np.isfinite(comp) & (dist >= NEAR_P), comp, np.nan)
    with warnings.catch_warnings():
        warnings.simplefilter("ignore")
        return np.nanmean(comp, axis=1)


def lag_mean(a, lo=LAG[0], hi=LAG[1]):
    """Mean of the finite values over frames t - hi .. t - lo (inclusive); NaN if none."""
    a = np.asarray(a, float)
    fin = np.isfinite(a)
    cs = np.r_[0.0, np.cumsum(np.where(fin, a, 0.0))]
    cn = np.r_[0, np.cumsum(fin)]
    t = np.arange(len(a))
    s, e = np.clip(t - hi, 0, len(a)), np.clip(t - lo + 1, 0, len(a))
    cnt = cn[e] - cn[s]
    with np.errstate(invalid="ignore", divide="ignore"):
        return np.where(cnt > 0, (cs[e] - cs[s]) / np.maximum(cnt, 1), np.nan)


def press_features(home, away):
    xy = np.concatenate([np.asarray(home, float), np.asarray(away, float)], axis=1)
    vel = np.stack([ss._cdiff(xy[:, :, 0]), ss._cdiff(xy[:, :, 1])], axis=2)
    speed = np.hypot(vel[:, :, 0], vel[:, :, 1])
    P = convergence_point(xy, speed)
    nh = np.asarray(home).shape[1]
    press = press_team(xy[:, :nh], vel[:, :nh], P) - press_team(xy[:, nh:], vel[:, nh:], P)
    return {"PRESS": press, "PRESS_1s": ss.smooth_nan(press, 25), "PRESS_LAG": lag_mean(press)}


def model_names(auc_tab, train):
    top = se.top_features(auc_tab, train)
    return top + [f for f in EXTRA if f not in top]


def fit_model(feats, frames_mis, auc_tab, train):
    from sklearn.linear_model import LogisticRegression
    from sklearn.preprocessing import StandardScaler
    names = model_names(auc_tab, train)
    Xs, ys = [], []
    for (mid, hi), (mask, truth) in sorted(frames_mis.items()):
        if mid in train:
            Xs.append(se.design(feats, (mid, hi), names)[mask]); ys.append(truth[mask] == H)
    X, y = np.vstack(Xs), np.concatenate(ys)
    sc = StandardScaler().fit(np.where(np.isfinite(X), X, np.nan))
    Z = np.nan_to_num(sc.transform(X), nan=0.0)
    lr = LogisticRegression(C=1.0, solver="lbfgs", max_iter=1000, random_state=0).fit(Z, y)
    return names, sc, lr


