FILES.append(('transition_flip.py', '2953260e5b9754957eb76573e100780c34fe5154d090f4eab2f7cd59ecd63210', r'''"""Report 0107 (overnight queue 2, B6, the free slot): a players-only TRANSITION FLIP score (both teams' forward runs
turning around) at true changes of team, especially interceptions, against calm frames, and its timing against
v1.4-dev's switch in regime R. PUBLIC DATA ONLY. Rules T0 to T7: claude_reports/0107_transition_flip.md (written
before this file).

    cd ~/Desktop/Bar/code && TMPDIR=/tmp conda run -n mtah-ext --no-capture-output python -B run_public.py transition_flip.py

Prints and writes claude_reports/0107_run.txt. Timing only on lines starting with "[". Planted tests:
tests/test_transition_flip.py. Library (for E1): forward_runs, flip.
"""

import os
import sys
import time
import warnings

import numpy as np

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
import harness  # noqa: E402

H, A, D, FPS = harness.H, harness.A, harness.D, harness.FPS
SMOOTH, W = 13, 25
SITS = ("PASS INTERCEPTED", "GROUND DUEL / TACKLE WON", "AERIAL DUEL", "BALL CLAIMED / INTERCEPTION",
        "LOOSE BALL / SCRAMBLE", "BALL TOUCH")
OUT_RUN = os.path.join(HERE, "claude_reports", "0107_run.txt")


def cmean(a, w=SMOOTH):
    """Centred NaN-aware mean over w frames (clipped)."""
    a = np.asarray(a, float)
    fin = np.isfinite(a)
    cs = np.r_[0.0, np.cumsum(np.where(fin, a, 0.0))]
    cn = np.r_[0, np.cumsum(fin)]
    n, h = len(a), w // 2
    t = np.arange(n)
    lo, hi = np.maximum(0, t - h), np.minimum(n, t + h + 1)
    cnt = cn[hi] - cn[lo]
    with np.errstate(invalid="ignore", divide="ignore"):
        return np.where(cnt > 0, (cs[hi] - cs[lo]) / np.maximum(cnt, 1), np.nan)


def wmean(a, lo_off, hi_off):
    """(n,): the NaN-aware mean of a over [t + lo_off, t + hi_off) (clipped; NaN if empty)."""
    a = np.asarray(a, float)
    fin = np.isfinite(a)
    cs = np.r_[0.0, np.cumsum(np.where(fin, a, 0.0))]
    cn = np.r_[0, np.cumsum(fin)]
    n = len(a)
    t = np.arange(n)
    lo, hi = np.clip(t + lo_off, 0, n), np.clip(t + hi_off, 0, n)
    cnt = cn[hi] - cn[lo]
    with np.errstate(invalid="ignore", divide="ignore"):
        return np.where(cnt > 0, (cs[hi] - cs[lo]) / np.maximum(cnt, 1), np.nan)


def forward_runs(xy, g, gk_slot):
    """T1: ADV(t) for one team: -g times the outfield centroid's x-velocity, smoothed."""
    xy = np.asarray(xy, float)
    keep = np.ones(xy.shape[1], bool)
    if gk_slot is not None:
        keep[gk_slot] = False
    with warnings.catch_warnings():
        warnings.simplefilter("ignore")
        cx = np.nanmean(xy[:, keep, 0], axis=1)
    v = np.full(len(cx), np.nan)
    v[2:-2] = (cx[4:] - cx[:-4]) * (FPS / 4.0)
    return cmean(-g * v)


def flip(adv_k, adv_o, w=W):
    """T2: FLIP towards k = (future [t + w, t + 2w) minus past [t - w, t)) of ADV_k minus the same for the other team."""
    dk = wmean(adv_k, w, 2 * w) - wmean(adv_k, -w, 0)
    do = wmean(adv_o, w, 2 * w) - wmean(adv_o, -w, 0)
    return dk - do


def auc(pos, neg):
    """Mann-Whitney AUC of pos against neg (ties count half); NaN if either is empty."""
    pos, neg = np.asarray(pos, float), np.asarray(neg, float)
    pos, neg = pos[np.isfinite(pos)], neg[np.isfinite(neg)]
    if not len(pos) or not len(neg):
        return float("nan")
    allv = np.concatenate([pos, neg])
    order = np.argsort(allv, kind="mergesort")
    ranks = np.empty(len(allv))
    sv = allv[order]
    i = 0
    while i < len(sv):
        j = i
        while j + 1 < len(sv) and sv[j + 1] == sv[i]:
            j += 1
        ranks[order[i:j + 1]] = (i + j) / 2 + 1
        i = j + 1
    rp = ranks[:len(pos)].sum()
    return float((rp - len(pos) * (len(pos) + 1) / 2) / (len(pos) * len(neg)))


def calm_frames(truth0, live, step=25, half=50):
    """T3: every step-th live frame whose merge-0 truth is one team on [t - half, t + half]; (frames, team)."""
    truth0 = np.asarray(truth0)
    n = len(truth0)
    out = []
    for t in range(half, n - half, step):
        if not live[t]:
            continue
        seg = truth0[t - half:t + half + 1]
        if seg[0] <= A and np.all(seg == seg[0]):
            out.append((t, int(seg[0])))
    return out


def first_at_least(score, lo, hi, theta):
    idx = np.flatnonzero(np.asarray(score[lo:hi]) >= theta)
    return lo + int(idx[0]) if len(idx) else None


def first_label(pred, lo, hi, k):
    idx = np.flatnonzero(np.asarray(pred[lo:hi]) == k)
    return lo + int(idx[0]) if len(idx) else None


def study():
    import explore_short_possessions_2 as ex2
    import night2_panel as n2
    import restart_shape_public as rs
    import shape_signals as ss
    lines = []

    def out(s=""):
        print(s, flush=True)
        lines.append(s)
    t0 = time.time()
    out("REPORT 0107 transition_flip: players-only flip of the teams' forward runs at true changes (public DFL)")
    with warnings.catch_warnings():
        warnings.simplefilter("ignore")
        ctx = n2.load_context(("R",), out)
        if ctx is None:
            out("STOP: C does not reproduce")
            return _finish(lines, 1)
        pred = {x: n2.decode14(ctx, "R", x) for x in ctx["ids"]}
        occ = n2.events(ctx)
    r1 = n2.mean_of(ctx["truths"][1.0], pred)
    ok = "%.4f" % r1 == "0.5002" and n2.n_occurrences(occ) == n2.OCC_0096
    out("PROOF: R 1 s %.4f (0.5002); occurrences %d (%d): %s" % (r1, n2.n_occurrences(occ), n2.OCC_0096,
                                                                 "PASS" if ok else "FAIL"))
    if not ok:
        out("STOP")
        return _finish(lines, 1)
    ch_rows, calm = [], []
    n_undecided = 0
    for m in ctx["ids"]:
        for hi, h in enumerate(harness.matches()[m]["halves"]):
            home, away = np.asarray(h["home"], float), np.asarray(h["away"], float)
            dr = rs.direction(home, away)
            if dr is None:
                n_undecided += 1
                continue
            adv = {H: forward_runs(home, dr[0], ss.goalkeeper(home, dr[0])),
                   A: forward_runs(away, dr[1], ss.goalkeeper(away, dr[1]))}
            fl = {H: flip(adv[H], adv[A]), A: flip(adv[A], adv[H])}
            live = ~np.asarray(ctx["C"][(m, hi)], bool)
            raw = ctx["raw"][m][hi]
            o = occ[(m, hi)]
            for s, k, direct in ex2.true_changes(raw):
                if not direct or not live[s]:
                    continue
                d = np.abs(o["frames"] - s)
                j = int(np.argmin(d)) if len(d) else None
                sit = o["sits"][j] if j is not None and d[j] <= 25 and o["sits"][j] in SITS else "other"
                ch_rows.append(dict(m=m, hi=hi, s=s, k=k, sit=sit, score=fl[k][s], fl=fl[k], pred=pred[m][hi]))
            for t, p in calm_frames(raw, live):
                calm.append(fl[1 - p][t])
    out("halves with an undecided direction (left out): %d; true direct changes on C-live frames %d; calm frames %d"
        % (n_undecided, len(ch_rows), len(calm)))
    calm = np.asarray(calm, float)
    theta = float(np.nanpercentile(calm, 90))
    out("calm FLIP: median %+.3f m/s, 90th percentile (theta) %+.3f m/s" % (np.nanmedian(calm), theta))
    decision = {}
    for sit in ("ALL",) + SITS + ("other",):
        sel = [r for r in ch_rows if sit == "ALL" or r["sit"] == sit]
        sc = [r["score"] for r in sel]
        a = auc(sc, calm)
        leads, n_v14_none, n_flip_only = [], 0, 0
        for r in sel:
            n = len(r["fl"])
            lo, hi_ = max(0, r["s"] - 50), min(n, r["s"] + 101)
            det = first_at_least(r["fl"], lo, hi_, theta)
            v = first_label(r["pred"], lo, hi_, r["k"])
            if v is None:
                n_v14_none += 1
                n_flip_only += det is not None
            elif det is not None:
                leads.append((v - det) / FPS)
        lq = np.percentile(leads, [25, 50, 75]) if leads else [np.nan] * 3
        out("FLIP %-28s | changes %4d | AUC against calm %.3f | median score %+.3f | lead (v1.4 minus flip) median "
            "%+.2f s [%+.2f, %+.2f] (n %d) | v1.4 never labels the new team within the window %d (flip detects %d)"
            % (sit, len(sel), a, np.nanmedian(sc) if sc else float("nan"), lq[1], lq[0], lq[2], len(leads),
               n_v14_none, n_flip_only))
        decision[sit] = (a, lq[1])
    a, ld = decision["PASS INTERCEPTED"]
    go = (a >= 0.75 - 1e-12) and (ld >= 0.5 - 1e-12)
    out("B6 DECISION (PASS INTERCEPTED: AUC %.3f >= 0.75 and median lead %+.2f s >= +0.5 s): %s"
        % (a, ld, "SOLVE B6" if go else "no SOLVE (handed to E1 as a candidate feature)"))
    out("[done in %d s]" % (time.time() - t0))
    return _finish(lines, 0)


def _finish(lines, code):
    with open(OUT_RUN, "w") as f:
        f.write("\n".join(lines) + "\n")
    return code


def main(argv=None):
    argv = sys.argv[1:] if argv is None else argv
    if argv:
        sys.exit("transition_flip.py takes no arguments")
    return study()


if __name__ == "__main__":
    sys.exit(main())
'''))

